window.CIT_TRAP=[{"id":"A01","set":"A","ch":"02","t":"N","q":"Which of the following is **NOT** a responsibility of Canadian citizenship?","zq":"下列哪一項「不是」加拿大公民的責任？","o":["Owning a home","Obeying the law","Serving on a jury when called to do so","Taking responsibility for oneself and one's family"],"zo":["擁有自己的房子","遵守法律","被傳喚時擔任陪審員","照顧自己和家人"],"a":0,"f":0,"e":"公民責任包括：守法、照顧自己與家人、擔任陪審員、投票、幫助社區、保護遺產與環境。買房子不是責任。","k":[["responsibility","責任"],["jury","陪審團"]]},{"id":"A02","set":"A","ch":"02","t":"S","q":"\"Habeas corpus\" gives you the right to:","zq":"「Habeas corpus（人身保護令）」給你什麼權利？","o":["Challenge unlawful detention by the state","Vote in municipal elections","Own land anywhere in Canada","Use either official language in court"],"zo":["挑戰政府的非法拘留","在市政選舉投票","在加拿大任何地方擁有土地","在法庭使用任一官方語言"],"a":0,"f":0,"e":"Habeas corpus 是拉丁文，意思是政府不能隨便把人關起來，你有權挑戰非法拘留。","k":[["unlawful","非法的"],["detention","拘留"]]},{"id":"A03","set":"A","ch":"02","t":"C","q":"Your neighbour receives a notice to **serve on a jury**. What should she do?","zq":"你的鄰居收到「擔任陪審員」的通知，她應該怎麼做？","o":["Serve when called; it is a responsibility of citizenship","Ignore it unless she wants to volunteer","Pay a fee to be excused automatically","Only citizens over 65 need to serve"],"zo":["被傳喚就去，這是公民責任","除非想當義工，否則不理","付錢就自動免除","只有 65 歲以上的公民需要去"],"a":0,"f":0,"e":"情境題：換成「鄰居收到通知」的故事，其實就是問「擔任陪審員是公民責任」。","k":[["notice","通知"],["serve on a jury","擔任陪審員"]]},{"id":"A04","set":"A","ch":"02","t":"C","q":"Someone says violence against a spouse is acceptable because of his cultural traditions. According to Canadian law, this is:","zq":"有人說因為文化傳統，對配偶施暴是可以接受的。依照加拿大法律，這是：","o":["A crime that is severely punished","Acceptable if it happens at home","Allowed for newcomers during their first three years","A matter only for religious leaders"],"zo":["會被嚴厲懲罰的罪行","在家裡發生就可以","新移民前三年可以","只由宗教領袖處理"],"a":0,"f":0,"e":"加拿大的開放不包括家暴、名譽殺人、女性割禮、強迫婚姻等野蠻習俗，這些都依法嚴懲。","k":[["spouse","配偶"],["severely","嚴厲地"]]},{"id":"A05","set":"A","ch":"02","t":"W","q":"Which statement about the **rule of law** in Canada is **TRUE**?","zq":"關於加拿大的「法治」，哪一句是「正確」的？","o":["Everyone, including police, judges and politicians, must follow the law","Government officials are above the law","The law applies only to citizens","Judges may ignore laws they disagree with"],"zo":["每個人，包括警察、法官、政治人物，都必須守法","政府官員可以不受法律約束","法律只適用於公民","法官可以不理自己不同意的法律"],"a":0,"f":0,"e":"rule of law = 法治：所有人都要守法，沒有人在法律之上。","k":[["rule of law","法治"],["above the law","凌駕法律之上"]]},{"id":"A06","set":"A","ch":"02","t":"T","q":"True or False: Military service is **compulsory** in Canada.","zq":"是非題：加拿大必須服兵役。","o":["True","False"],"zo":["對","錯"],"a":1,"f":1,"e":"錯。加拿大沒有強制兵役。","k":[["compulsory","強制的"]]},{"id":"A07","set":"A","ch":"03","t":"S","q":"In the Inuktitut language, the word \"**Inuit**\" means:","zq":"在因紐特語中，「Inuit」這個字是什麼意思？","o":["The people","Our land","Village","Northern lights"],"zo":["人們","我們的土地","村莊","北極光"],"a":0,"f":0,"e":"Inuit = the people。另外 Nunavut = our land（我們的土地），kanata = village（村莊）。三個容易混淆。","k":[["means","意思是"]]},{"id":"A08","set":"A","ch":"03","t":"F","q":"Among Aboriginal people in Canada, which group is the **largest**?","zq":"在加拿大原住民中，哪一群「人數最多」？","o":["First Nations","Métis","Inuit","They are all the same size"],"zo":["第一民族","梅蒂斯人","因紐特人","一樣多"],"a":0,"f":0,"e":"約 65% 第一民族、30% 梅蒂斯人、4% 因紐特人。","k":[["largest","最大、最多"]]},{"id":"A09","set":"A","ch":"03","t":"S","q":"The **majority** of French-speaking Canadians live in:","zq":"「大部分」說法語的加拿大人住在：","o":["Quebec","New Brunswick","Manitoba","Nova Scotia"],"zo":["魁北克","新布藍瑞克","曼尼托巴","新斯科細亞"],"a":0,"f":0,"e":"majority = 大多數。大部分法語人口在魁北克（Francophones = 說法語的人）。","k":[["majority","大多數"],["francophone","說法語的人"]]},{"id":"A10","set":"A","ch":"03","t":"T","q":"True or False: **Quebec** is Canada's only officially bilingual province.","zq":"是非題：魁北克是加拿大唯一的官方雙語省份。","o":["True","False"],"zo":["對","錯"],"a":1,"f":1,"e":"錯。是 New Brunswick（新布藍瑞克）。","k":[["bilingual","雙語的"]]},{"id":"A11","set":"A","ch":"04","t":"R","q":"Between 1534 and 1542, who crossed the Atlantic three times and **claimed** the land for the King of France?","zq":"1534 至 1542 年間，誰三次橫渡大西洋，並為法國國王「宣佈擁有」這片土地？","o":["Jacques Cartier","John Cabot","Pierre de Monts","James Wolfe"],"zo":["雅克・卡蒂亞","約翰・卡伯特","皮耶・德蒙","詹姆斯・沃夫"],"a":0,"f":0,"e":"Cartier = 為法國探索聖羅倫斯河；Cabot = 為英國、1497、東岸地圖。","k":[["claimed","宣稱擁有"]]},{"id":"A12","set":"A","ch":"04","t":"W","q":"Which statement about the **Battle of the Plains of Abraham** (1759) is **TRUE**?","zq":"關於「亞伯拉罕平原戰役」（1759），哪一句「正確」？","o":["The British defeated the French at Quebec City, ending France's empire in America","The French defeated the British and took Montreal","The United States invaded Canada","It was the last battle of the First World War"],"zo":["英國在魁北克市擊敗法國，結束了法國在美洲的帝國","法國擊敗英國並攻下蒙特婁","美國入侵加拿大","是一戰最後一場戰役"],"a":0,"f":0,"e":"1759 英軍（Wolfe）打敗法軍（Montcalm），兩位將軍都戰死。","k":[["defeated","擊敗"],["empire","帝國"]]},{"id":"A13","set":"A","ch":"04","t":"N","q":"Which of the following was **NOT** a result of the Constitutional Act of 1791?","zq":"下列哪一項「不是」1791 年憲法法案的結果？","o":["It created the Dominion of Canada","It divided the Province of Quebec into Upper and Lower Canada","It gave both Canadas legislative assemblies elected by the people","It made the name \"Canada\" official"],"zo":["建立了加拿大自治領","把魁北克省分成上加拿大和下加拿大","給上、下加拿大各自的民選議會","讓「Canada」成為正式名稱"],"a":0,"f":0,"e":"加拿大自治領（Dominion of Canada）是 1867 年聯邦成立，不是 1791 年。","k":[["result","結果"],["divided","分割"]]},{"id":"A14","set":"A","ch":"04","t":"S","q":"The **Underground Railroad** was:","zq":"「地下鐵路」是：","o":["A network that helped slaves escape from the United States to freedom in Canada","Canada's first subway line","A railway built under the Rocky Mountains","The coal mines of Nova Scotia"],"zo":["幫助奴隸從美國逃到加拿大獲得自由的秘密網絡","加拿大第一條地鐵","在洛磯山下建的鐵路","新斯科細亞的煤礦"],"a":0,"f":0,"e":"陷阱：字面是地下鐵路，其實不是鐵路，是幫助逃奴的秘密網絡。","k":[["network","網絡"],["escape","逃跑"]]},{"id":"A15","set":"A","ch":"04","t":"R","q":"In 1813, who walked about 30 km to **warn** Lieutenant James FitzGibbon of an American attack?","zq":"1813 年，誰走了約 30 公里去「警告」FitzGibbon 中尉美軍要攻擊？","o":["Laura Secord","Isaac Brock","Tecumseh","Emily Stowe"],"zo":["蘿拉・塞科德","艾薩克・布洛克","特庫姆塞","艾蜜莉・斯托"],"a":0,"f":0,"e":"走 30 公里報信 = Laura Secord（女性）。","k":[["warn","警告"]]},{"id":"A16","set":"A","ch":"04","t":"S","q":"\"**Responsible government**\" means that:","zq":"「責任政府」的意思是：","o":["Ministers of the Crown must have the support of a majority of the elected representatives to govern","Citizens are responsible for paying taxes","The King makes all laws personally","Each province governs itself without a federal government"],"zo":["內閣部長必須得到多數民選議員支持才能執政","公民有責任繳稅","國王親自制定所有法律","各省自治，沒有聯邦政府"],"a":0,"f":0,"e":"題目沒問「誰」，而是問定義。重點：政府要有民選議會多數支持。","k":[["majority","多數"],["elected representatives","民選代表"]]},{"id":"A17","set":"A","ch":"04","t":"R","q":"What happened on **July 1, 1867**?","zq":"「1867 年 7 月 1 日」發生了什麼事？","o":["The Dominion of Canada was created (Confederation)","The Charter of Rights and Freedoms was signed","Women won the right to vote","Newfoundland joined Canada"],"zo":["加拿大自治領成立（聯邦）","權利與自由憲章簽署","婦女獲得投票權","紐芬蘭加入加拿大"],"a":0,"f":0,"e":"反問題：題目給日期，問事件。1867 = 聯邦成立；1982 = 憲章。","k":[["Confederation","聯邦"]]},{"id":"A18","set":"A","ch":"04","t":"R","q":"Sir John A. Macdonald is best known as:","zq":"約翰・A・麥克唐納爵士最為人所知的身份是：","o":["Canada's first Prime Minister","Canada's first Governor General","Leader of the Métis uprising","The founder of Quebec City"],"zo":["加拿大第一任總理","第一任總督","梅蒂斯人起義領袖","魁北克市創建者"],"a":0,"f":0,"e":"他的肖像在 10 元紙鈔上，生日 1 月 11 日為 Sir John A. Macdonald Day。","k":[["best known as","最為人知的是"]]},{"id":"A19","set":"A","ch":"04","t":"R","q":"Which province joined Confederation (1870) as a result of the first Métis uprising led by **Louis Riel**?","zq":"哪一省因為 Louis Riel 領導的第一次梅蒂斯人起義，而加入聯邦（1870）？","o":["Manitoba","Saskatchewan","Alberta","British Columbia"],"zo":["曼尼托巴","薩克其萬","亞伯達","卑詩省"],"a":0,"f":0,"e":"Red River 起義 → 1870 年曼尼托巴建省。","k":[["uprising","起義"],["as a result of","由於"]]},{"id":"A20","set":"A","ch":"04","t":"W","q":"Which statement about **Chinese workers** and the Canadian Pacific Railway is **TRUE**?","zq":"關於「華工」與加拿大太平洋鐵路，哪一句「正確」？","o":["They helped build the railway; afterwards Ottawa imposed a head tax on Chinese immigrants","They were not allowed to work on the railway","They were paid more than all other workers","They owned the railway company"],"zo":["他們協助建造鐵路；之後政府對華人移民徵收人頭稅","他們不被允許參與建造","他們工資比其他工人都高","他們擁有鐵路公司"],"a":0,"f":0,"e":"華工對鐵路貢獻很大，之後卻被徵人頭稅。政府在 2006 年道歉。","k":[["head tax","人頭稅"],["imposed","徵收、強加"]]},{"id":"A21","set":"A","ch":"04","t":"R","q":"The poem \"**In Flanders Fields**\" was written by:","zq":"詩作《在法蘭德斯戰場》的作者是：","o":["Lieutenant Colonel John McCrae","Sir Arthur Currie","Sir Isaac Brock","Agnes Macphail"],"zo":["約翰・麥克雷中校","亞瑟・柯里爵士","布洛克爵士","艾格妮絲・麥克費爾"],"a":0,"f":0,"e":"John McCrae，軍醫，1915 年寫下此詩，至今在陣亡將士紀念日朗誦。","k":[["poem","詩"]]},{"id":"A22","set":"A","ch":"04","t":"R","q":"On **D-Day**, June 6, 1944, Canadian soldiers captured which beach?","zq":"1944 年 6 月 6 日「諾曼第登陸日」，加拿大士兵攻下哪個海灘？","o":["Juno Beach","Omaha Beach","Gold Beach","Utah Beach"],"zo":["朱諾海灘","奧馬哈海灘","黃金海灘","猶他海灘"],"a":0,"f":0,"e":"Juno Beach。","k":[["captured","攻下"]]},{"id":"A23","set":"A","ch":"04","t":"R","q":"In what year did Canada **become a country** (Confederation)?","zq":"加拿大在哪一年「成為一個國家」（聯邦成立）？","o":["1867","1982","1759","1931"],"zo":["1867","1982","1759","1931"],"a":0,"f":0,"e":"最常搞混：1867 聯邦成立；1982 憲法修改＋憲章；1759 亞伯拉罕平原戰役。","k":[["become a country","成為國家"]]},{"id":"A24","set":"A","ch":"04","t":"T","q":"True or False: **Lower Canada** later became the province of Ontario.","zq":"是非題：下加拿大後來成為安大略省。","o":["True","False"],"zo":["對","錯"],"a":1,"f":1,"e":"錯。下加拿大 = 魁北克；上加拿大 = 安大略。","k":[]},{"id":"A25","set":"A","ch":"05","t":"R","q":"**Terry Fox** is remembered for:","zq":"泰瑞・福克斯被紀念是因為：","o":["His \"Marathon of Hope\" run across Canada to raise money for cancer research","Inventing basketball","Discovering insulin","Being the first woman in Parliament"],"zo":["他橫跨加拿大的「希望馬拉松」，為癌症研究募款","發明籃球","發現胰島素","第一位女性國會議員"],"a":0,"f":0,"e":"1980 年因癌症失去一條腿，仍跑步為癌症研究募款。","k":[["raise money","募款"],["cancer research","癌症研究"]]},{"id":"A26","set":"A","ch":"05","t":"S","q":"The **Stanley Cup** was donated by:","zq":"史丹利杯是由誰捐贈的？","o":["Lord Stanley, a Governor General, in 1892","Sir John A. Macdonald","A hockey team from Montreal","Queen Victoria"],"zo":["1892 年總督 Stanley 勳爵","麥克唐納","蒙特婁的冰球隊","維多利亞女王"],"a":0,"f":0,"e":"donated = 捐贈。Stanley 勳爵是總督。","k":[["donated","捐贈"]]},{"id":"A27","set":"A","ch":"05","t":"R","q":"Which famous invention is linked to **Alexander Graham Bell**?","zq":"哪項著名發明與「貝爾」有關？","o":["The telephone","The snowmobile","The electric light bulb","The pacemaker"],"zo":["電話","雪地摩托車","電燈泡","心律調節器"],"a":0,"f":0,"e":"Bell 在安大略 Brantford 構想出電話。","k":[["linked to","與……有關"]]},{"id":"A28","set":"A","ch":"06","t":"S","q":"Who is the **Head of Government** in Canada?","zq":"誰是加拿大的「政府首腦」？","o":["The Prime Minister","The Sovereign","The Governor General","The Speaker of the House"],"zo":["總理","君主","總督","下議院議長"],"a":0,"f":0,"e":"Head of Government = 總理（Prime Minister）。","k":[["Head of Government","政府首腦"]]},{"id":"A29","set":"A","ch":"06","t":"S","q":"The leader of a **provincial** government is called the:","zq":"「省政府」的領導人稱為：","o":["Premier","Prime Minister","Lieutenant Governor","Governor General"],"zo":["省長","總理","省督","總督"],"a":0,"f":0,"e":"Premier = 省長（民選政黨領袖）；Prime Minister = 聯邦總理。","k":[["provincial","省的"]]},{"id":"A30","set":"A","ch":"06","t":"S","q":"**Members of Parliament (MPs)** are:","zq":"「國會議員（MP）」是：","o":["Elected by the people to sit in the House of Commons","Appointed by the Prime Minister","Appointed by the Governor General until age 75","Chosen by the Senate"],"zo":["由人民選出，坐在下議院","由總理任命","由總督任命到 75 歲","由參議院選出"],"a":0,"f":0,"e":"MP 選出來的；Senator 任命的。","k":[["elected","選出"]]},{"id":"A31","set":"A","ch":"06","t":"N","q":"Which of the following is **NOT** a federal responsibility?","zq":"下列哪一項「不是」聯邦政府的職責？","o":["Highways","National defence","Foreign policy","Criminal law"],"zo":["公路","國防","外交政策","刑法"],"a":0,"f":0,"e":"公路是省的；國防、外交、刑法是聯邦的。","k":[["federal","聯邦的"],["foreign policy","外交政策"]]},{"id":"A32","set":"A","ch":"06","t":"S","q":"The **Cabinet** is made up of:","zq":"「內閣」由誰組成？","o":["Ministers chosen by the Prime Minister, mostly from among MPs","All senators","Provincial premiers","Supreme Court judges"],"zo":["總理挑選的部長，大多是國會議員","所有參議員","各省省長","最高法院法官"],"a":0,"f":0,"e":"Cabinet ministers 由總理挑選。","k":[["Cabinet","內閣"],["ministers","部長"]]},{"id":"A33","set":"A","ch":"06","t":"S","q":"When the party in power holds **LESS** than half of the seats in the House of Commons, it is called a:","zq":"當執政黨在下議院的席次「少於」一半，稱為：","o":["Minority government","Majority government","Official Opposition","Coalition senate"],"zo":["少數政府","多數政府","官方反對黨","聯合參議院"],"a":0,"f":0,"e":"less than half = 少於一半 → minority（少數）。","k":[["less than half","少於一半"],["minority","少數"]]},{"id":"A34","set":"A","ch":"07","t":"C","q":"Your employer asks you **how you voted**. Which is **TRUE**?","zq":"你的老闆問你「投給誰」。哪一句「正確」？","o":["You do not have to tell anyone; the law protects your secret ballot","You must tell your employer","You must tell only the police","Your vote is published online"],"zo":["你不必告訴任何人，法律保護秘密投票","你必須告訴老闆","你只需告訴警察","你的選票會在網上公佈"],"a":0,"f":0,"e":"secret ballot = 秘密投票。","k":[["secret ballot","秘密投票"]]},{"id":"A35","set":"A","ch":"07","t":"S","q":"A candidate who does **not belong to a political party** runs as an:","zq":"「不屬於任何政黨」的候選人稱為：","o":["Independent","Opposition member","Senator","Minister"],"zo":["獨立候選人","反對黨議員","參議員","部長"],"a":0,"f":0,"e":"independent = 獨立（無黨籍）。","k":[["candidate","候選人"],["independent","無黨籍"]]},{"id":"A36","set":"A","ch":"08","t":"S","q":"In Canada, a person **accused of a crime** is considered:","zq":"在加拿大，「被控犯罪」的人被視為：","o":["Innocent until proven guilty","Guilty until proven innocent","Guilty if arrested by the police","Innocent only if a lawyer is paid"],"zo":["在證明有罪前是無罪的","在證明無罪前是有罪的","被警察逮捕就有罪","付錢請律師才算無罪"],"a":0,"f":0,"e":"presumption of innocence = 無罪推定。","k":[["accused","被控告的"],["guilty","有罪的"]]},{"id":"A37","set":"A","ch":"08","t":"C","q":"You have a legal problem but **cannot afford** a lawyer. What can you do?","zq":"你遇到法律問題但「請不起」律師，可以怎麼做？","o":["Use legal aid services, which are free or low-cost","Nothing; only people with money can go to court","Ask the judge to be your lawyer","Ask your MP to decide the case"],"zo":["使用免費或低收費的法律援助","沒辦法，只有有錢人能上法院","請法官當你的律師","請議員判決"],"a":0,"f":0,"e":"afford = 負擔得起。legal aid = 法律援助。","k":[["afford","負擔得起"],["legal aid","法律援助"]]},{"id":"A38","set":"A","ch":"08","t":"T","q":"True or False: The RCMP is the provincial police force in **Ontario**.","zq":"是非題：皇家騎警是安大略的省警察。","o":["True","False"],"zo":["對","錯"],"a":1,"f":1,"e":"錯。安大略的省警察是 OPP（Ontario Provincial Police）。","k":[["police force","警察部隊"]]},{"id":"A39","set":"A","ch":"09","t":"R","q":"Which animal is an official symbol of Canada and appears on the **5-cent coin**?","zq":"哪種動物是加拿大官方象徵，並印在「5 分硬幣」上？","o":["The beaver","The loon","The caribou","The polar bear"],"zo":["河狸","潛鳥","馴鹿","北極熊"],"a":0,"f":0,"e":"5 分 = beaver（河狸）；1 元 = loon（潛鳥，loonie）；25 分 = 馴鹿。","k":[["beaver","河狸"],["coin","硬幣"]]},{"id":"A40","set":"A","ch":"09","t":"S","q":"In Canada, **the Crown** is a symbol of:","zq":"在加拿大，「王冠」象徵：","o":["Government, including Parliament, the legislatures, the courts, police services and the Armed Forces","The Hudson's Bay Company","Hockey champions","The Catholic Church"],"zo":["政府，包括國會、議會、法院、警察和軍隊","哈德遜灣公司","冰球冠軍","天主教會"],"a":0,"f":0,"e":"the Crown = 國家權力的象徵。","k":[["Crown","王冠、王室"]]},{"id":"A41","set":"A","ch":"09","t":"R","q":"Which holiday celebrates the **anniversary of Confederation**?","zq":"哪個節日慶祝「聯邦成立週年」？","o":["Canada Day (July 1)","Victoria Day","Remembrance Day","Thanksgiving"],"zo":["加拿大國慶日（7 月 1 日）","維多利亞日","陣亡將士紀念日","感恩節"],"a":0,"f":0,"e":"anniversary = 週年紀念。","k":[["anniversary","週年"]]},{"id":"A42","set":"A","ch":"10","t":"F","q":"Which country is Canada's **largest** trading partner?","zq":"哪個國家是加拿大「最大」的貿易夥伴？","o":["The United States","China","The United Kingdom","Mexico"],"zo":["美國","中國","英國","墨西哥"],"a":0,"f":0,"e":"美國。兩國有世界上最長的不設防國界。","k":[["trading partner","貿易夥伴"]]},{"id":"A43","set":"A","ch":"11","t":"N","q":"Which of the following is **NOT** one of Canada's five regions?","zq":"下列哪一個「不是」加拿大的五大區域之一？","o":["The Southern Provinces","The Atlantic Provinces","The Prairie Provinces","The North"],"zo":["南部省份","大西洋省份","草原省份","北部"],"a":0,"f":0,"e":"五大區域：大西洋、中部、草原、西岸、北部。","k":[["region","區域"]]},{"id":"A44","set":"A","ch":"11","t":"F","q":"Which is the **smallest** province, known as the \"birthplace of Confederation\"?","zq":"哪一個是「最小」的省，被稱為「聯邦誕生地」？","o":["Prince Edward Island","Nova Scotia","New Brunswick","Newfoundland and Labrador"],"zo":["愛德華王子島","新斯科細亞","新布藍瑞克","紐芬蘭與拉布拉多"],"a":0,"f":0,"e":"1864 年夏洛特敦會議在 PEI 舉行，但 PEI 1873 年才加入聯邦。","k":[["smallest","最小的"],["birthplace","誕生地"]]},{"id":"A45","set":"A","ch":"11","t":"R","q":"Which territory is famous for the **Klondike Gold Rush** of the 1890s?","zq":"哪個地區以 1890 年代的「克朗代克淘金潮」聞名？","o":["Yukon","Nunavut","Northwest Territories","British Columbia"],"zo":["育空","努納福特","西北地區","卑詩省"],"a":0,"f":0,"e":"Yukon，首府 Whitehorse。","k":[["gold rush","淘金潮"]]},{"id":"A46","set":"A","ch":"11","t":"S","q":"**Pier 21** in Halifax is known as:","zq":"哈利法克斯的「21 號碼頭」以什麼聞名？","o":["The gateway for over one million immigrants between 1928 and 1971","Canada's largest naval base","The place where the Last Spike was driven","The site of the first Parliament"],"zo":["1928–1971 年間超過一百萬移民的入境門戶","加拿大最大海軍基地","最後一根道釘的地方","第一屆國會所在地"],"a":0,"f":0,"e":"gateway = 門戶。","k":[["gateway","門戶"],["immigrants","移民"]]},{"id":"B01","set":"B","ch":"02","t":"S","q":"The Canadian Charter of Rights and Freedoms was **entrenched** in which document?","zq":"《權利與自由憲章》被「寫入（確立）」在哪一份文件中？","o":["The Constitution of Canada, in 1982","The British North America Act, in 1867","Magna Carta, in 1215","The Quebec Act, in 1774"],"zo":["1982 年的加拿大憲法","1867 年的英屬北美法案","1215 年的大憲章","1774 年的魁北克法案"],"a":0,"f":0,"e":"1982 年憲法修改時加入了《權利與自由憲章》。entrenched = 牢固地寫進去。","k":[["entrenched","確立、寫入（法律中）"],["Charter","憲章"]]},{"id":"B02","set":"B","ch":"02","t":"W","q":"Which statement about **mobility rights** is **TRUE**?","zq":"關於「遷徙權」，哪一句是「正確」的？","o":["Canadians can live and work anywhere in Canada, enter and leave the country freely, and apply for a passport","Canadians need permission to move to another province","Only citizens born in Canada may leave and re-enter freely","Mobility rights apply only to people over 21"],"zo":["加拿大人可在全國任何地方居住工作、自由出入境、申請護照","搬到別省需要許可","只有在加拿大出生的公民才能自由出入境","遷徙權只適用於 21 歲以上"],"a":0,"f":0,"e":"mobility = 移動。遷徙權：在任何地方生活工作、自由出入境、申請護照。","k":[["mobility","移動、遷徙"],["statement","敘述、句子"]]},{"id":"B03","set":"B","ch":"02","t":"T","q":"True or False: In Canada, men and women are **equal** under the law.","zq":"是非題：在加拿大，男女在法律面前平等。","o":["True","False"],"zo":["對","錯"],"a":0,"f":1,"e":"正確。Discover Canada 明確寫出男女在法律上平等。","k":[["equal","平等"]]},{"id":"B04","set":"B","ch":"02","t":"S","q":"Military service in Canada is:","zq":"在加拿大服兵役是：","o":["Not compulsory, but serving is a noble way to contribute","Compulsory for all men aged 18 to 25","Compulsory for all new citizens","Not allowed for dual citizens"],"zo":["不是義務的，但服役是貢獻國家的高尚方式","18–25 歲男性必須服役","所有新公民必須服役","雙重國籍者不可服役"],"a":0,"f":0,"e":"compulsory = 強制的。加拿大沒有強制兵役。","k":[["compulsory","強制的、義務的"],["noble","高尚的"]]},{"id":"B05","set":"B","ch":"02","t":"S","q":"According to the Charter, **multiculturalism** is:","zq":"根據憲章，「多元文化」是：","o":["A fundamental characteristic of Canadian heritage and identity","A temporary government program","A policy that applies only in large cities","A right that replaces official languages"],"zo":["加拿大遺產與身份認同的基本特徵","暫時性的政府計畫","只適用大城市的政策","取代官方語言的權利"],"a":0,"f":0,"e":"fundamental characteristic = 基本特徵。","k":[["fundamental","基本的"],["identity","身份認同"]]},{"id":"B06","set":"B","ch":"03","t":"S","q":"Canada is often described as being built by **three founding peoples**. Who are they?","zq":"加拿大常被說是由「三個建國民族」建立的，是哪三個？","o":["Aboriginal, French and British","English, Scottish and Irish","First Nations, Inuit and Métis","French, Spanish and Portuguese"],"zo":["原住民、法國人、英國人","英格蘭、蘇格蘭、愛爾蘭人","第一民族、因紐特人、梅蒂斯人","法國、西班牙、葡萄牙人"],"a":0,"f":0,"e":"陷阱：第一民族、因紐特、梅蒂是「原住民的三個群體」，不是「三個建國民族」。建國民族 = 原住民＋法國＋英國。","k":[["founding","建國的"],["peoples","民族"]]},{"id":"B07","set":"B","ch":"03","t":"R","q":"Which Aboriginal people are of **mixed** Aboriginal and European **ancestry**, with most living in the Prairie provinces?","zq":"哪一群原住民是原住民與歐洲人的「混血後代」，大多住在草原省份？","o":["Métis","Inuit","First Nations","Acadians"],"zo":["梅蒂斯人","因紐特人","第一民族","阿卡迪亞人"],"a":0,"f":0,"e":"mixed ancestry = 混血祖先 → Métis 梅蒂斯人。","k":[["ancestry","祖先、血統"],["mixed","混合的"]]},{"id":"B08","set":"B","ch":"03","t":"S","q":"English and French have **equal status** in:","zq":"英語和法語在哪裡享有「同等地位」？","o":["Parliament and throughout the federal government","Quebec only","Schools only","The courts of Ontario only"],"zo":["國會和整個聯邦政府","只有魁北克","只有學校","只有安省法院"],"a":0,"f":0,"e":"兩種官方語言在國會及整個聯邦政府地位平等。","k":[["equal status","同等地位"]]},{"id":"B09","set":"B","ch":"03","t":"R","q":"The \"**Great Upheaval**\" refers to:","zq":"「大動盪（Great Upheaval）」指的是：","o":["The deportation of the Acadians by the British (1755–1763)","The Quiet Revolution in Quebec","The Klondike Gold Rush","The Rebellions of 1837–38"],"zo":["英國驅逐阿卡迪亞人（1755–1763）","魁北克的寧靜革命","克朗代克淘金潮","1837–38 年叛亂"],"a":0,"f":0,"e":"refers to = 指的是。Great Upheaval = 阿卡迪亞人被英國驅逐。","k":[["refers to","指的是"],["deportation","驅逐出境"]]},{"id":"B10","set":"B","ch":"04","t":"S","q":"The name \"Canada\" is believed to come from \"**kanata**\", an Iroquoian word meaning:","zq":"「Canada」據說來自易洛魁語「kanata」，意思是：","o":["Village","Big land","The people","Our land"],"zo":["村莊","大地","人們","我們的土地"],"a":0,"f":0,"e":"kanata = village 村莊。","k":[["Iroquoian","易洛魁語的"]]},{"id":"B11","set":"B","ch":"04","t":"R","q":"Which law of 1774 allowed **religious freedom for Catholics** and let them hold public office?","zq":"哪一條 1774 年的法律讓「天主教徒有宗教自由」並可擔任公職？","o":["The Quebec Act","The Constitutional Act","The British North America Act","The Official Languages Act"],"zo":["魁北克法案","憲法法案（1791）","英屬北美法案","官方語言法"],"a":0,"f":0,"e":"Quebec Act 1774：天主教宗教自由、可任公職、恢復法國民法。","k":[["hold public office","擔任公職"]]},{"id":"B12","set":"B","ch":"04","t":"R","q":"**Upper Canada** later became which province?","zq":"「上加拿大」後來成為哪一省？","o":["Ontario","Quebec","Manitoba","New Brunswick"],"zo":["安大略","魁北克","曼尼托巴","新布藍瑞克"],"a":0,"f":0,"e":"陷阱：Upper（上）＝ 安大略；Lower（下）＝ 魁北克。以聖羅倫斯河上下游區分，不是地圖的上下。","k":[["Upper","上（游）"],["Lower","下（游）"]]},{"id":"B13","set":"B","ch":"04","t":"R","q":"Which company, founded in 1670, was given control of the **fur trade** north and west of the Great Lakes?","zq":"哪家成立於 1670 年的公司，掌控了五大湖北部和西部的「毛皮貿易」？","o":["Hudson's Bay Company","Canadian Pacific Railway","North West Mounted Police","Bank of Montreal"],"zo":["哈德遜灣公司","加拿大太平洋鐵路","西北騎警","蒙特婁銀行"],"a":0,"f":0,"e":"1670 + fur trade = Hudson's Bay Company。","k":[["fur trade","毛皮貿易"]]},{"id":"B14","set":"B","ch":"04","t":"R","q":"Who led the capture of Detroit in 1812 but was **killed** at the Battle of Queenston Heights?","zq":"誰在 1812 年攻下底特律，但在昆士頓高地戰役「陣亡」？","o":["Major-General Sir Isaac Brock","Tecumseh","Charles de Salaberry","Sir John A. Macdonald"],"zo":["布洛克少將","特庫姆塞","德薩拉伯里","麥克唐納"],"a":0,"f":0,"e":"Brock = 攻下底特律、戰死於昆士頓高地。Tecumseh 是協助防衛的肖尼族酋長。","k":[["capture","攻佔"],["killed","陣亡"]]},{"id":"B15","set":"B","ch":"04","t":"F","q":"Which British North American colony was the **FIRST** to achieve full responsible government (1847–48)?","zq":"哪個英屬北美殖民地「第一個」實現完全責任政府（1847–48）？","o":["Nova Scotia","Upper Canada","Lower Canada","British Columbia"],"zo":["新斯科細亞","上加拿大","下加拿大","卑詩省"],"a":0,"f":0,"e":"第一個 = Nova Scotia。1849 年聯合加拿大的第一位責任政府領袖是 La Fontaine。兩題容易混在一起。","k":[["achieve","達成"],["colony","殖民地"]]},{"id":"B16","set":"B","ch":"04","t":"N","q":"Which province was **NOT** one of the four original provinces in 1867?","zq":"哪一省「不是」1867 年最初的四個省之一？","o":["Manitoba","Ontario","Quebec","Nova Scotia"],"zo":["曼尼托巴","安大略","魁北克","新斯科細亞"],"a":0,"f":0,"e":"原始四省：安大略、魁北克、新斯科細亞、新布藍瑞克。曼尼托巴 1870 年才加入。","k":[["original","最初的"]]},{"id":"B17","set":"B","ch":"04","t":"F","q":"Who was the **first French-Canadian** Prime Minister after Confederation?","zq":"聯邦成立後，誰是「第一位法裔加拿大人」總理？","o":["Sir Wilfrid Laurier","Sir George-Étienne Cartier","Sir Louis-Hippolyte La Fontaine","Louis Riel"],"zo":["勞里埃爵士","卡蒂埃爵士","拉封丹爵士","路易・瑞爾"],"a":0,"f":0,"e":"Laurier，肖像在 5 元紙鈔。注意 George-Étienne Cartier 是聯邦之父，不是總理。","k":[["French-Canadian","法裔加拿大人"]]},{"id":"B18","set":"B","ch":"04","t":"R","q":"What was created in 1873 to **keep the peace** in the West and negotiate with First Nations?","zq":"1873 年成立什麼，用來在西部「維持治安」並與第一民族談判？","o":["The North West Mounted Police (forerunner of the RCMP)","The Canadian Army","The Hudson's Bay Company","The Supreme Court"],"zo":["西北騎警（皇家騎警的前身）","加拿大陸軍","哈德遜灣公司","最高法院"],"a":0,"f":0,"e":"forerunner = 前身。NWMP → 今天的 RCMP。","k":[["forerunner","前身"],["keep the peace","維持治安"]]},{"id":"B19","set":"B","ch":"04","t":"S","q":"Canadian soldiers' victory at **Vimy Ridge** in April 1917 is remembered because:","zq":"1917 年 4 月加拿大士兵在「維米嶺」勝利被紀念，是因為：","o":["Their courage and sacrifice helped earn Canada its place as a nation","It ended the Second World War","It was fought against the United States","No Canadians were killed"],"zo":["他們的勇氣與犧牲讓加拿大贏得國家的地位","結束了二戰","是對抗美國的戰役","沒有加拿大人陣亡"],"a":0,"f":0,"e":"維米嶺戰役（一戰）約 10,500 人死傷，常說「加拿大在維米嶺成為一個國家」。","k":[["courage","勇氣"],["sacrifice","犧牲"]]},{"id":"B20","set":"B","ch":"04","t":"F","q":"Which was the **FIRST province** to give women the right to vote (1916)?","zq":"哪一省「第一個」給予女性投票權（1916）？","o":["Manitoba","Ontario","Quebec","Nova Scotia"],"zo":["曼尼托巴","安大略","魁北克","新斯科細亞"],"a":0,"f":0,"e":"陷阱：題目問「第一個省」，不是聯邦。曼尼托巴 1916；聯邦 1917–1918；魁北克最晚（1940）。","k":[["right to vote","投票權"]]},{"id":"B21","set":"B","ch":"04","t":"R","q":"The people of which country still **thank** Canada every year for helping to **liberate** them in 1944–45?","zq":"哪個國家的人民至今每年「感謝」加拿大在 1944–45 年幫他們「解放」？","o":["The Netherlands","France","Italy","Belgium"],"zo":["荷蘭","法國","義大利","比利時"],"a":0,"f":0,"e":"荷蘭每年送鬱金香到渥太華致謝。","k":[["liberate","解放"]]},{"id":"B22","set":"B","ch":"04","t":"S","q":"In **1982**, what happened to Canada's Constitution?","zq":"「1982 年」，加拿大憲法發生了什麼事？","o":["It was amended so it could be changed without British approval, and the Charter was added","Canada became a country for the first time","The Constitution was cancelled","Quebec left Confederation"],"zo":["修改為不需英國批准即可修改，並加入憲章","加拿大首次成為國家","憲法被廢除","魁北克退出聯邦"],"a":0,"f":0,"e":"amended = 修改。1982 年憲法「回歸」並加入權利與自由憲章。","k":[["amended","修改"],["approval","批准"]]},{"id":"B23","set":"B","ch":"05","t":"S","q":"What is Canada's official **SUMMER** sport?","zq":"加拿大官方的「夏季」運動是什麼？","o":["Lacrosse","Hockey","Canadian football","Baseball"],"zo":["長曲棍球（長曲棍球）","冰球","加拿大式足球","棒球"],"a":0,"f":0,"e":"陷阱：冰球是「冬季」國家運動；長曲棍球是「夏季」官方運動。看清楚 SUMMER 或 WINTER。","k":[["official","官方的"],["summer","夏季"]]},{"id":"B24","set":"B","ch":"05","t":"R","q":"Which sport was **invented** by Canadian James Naismith in 1891?","zq":"哪一項運動是加拿大人 James Naismith 在 1891 年「發明」的？","o":["Basketball","Hockey","Lacrosse","Curling"],"zo":["籃球","冰球","長曲棍球","冰壺"],"a":0,"f":0,"e":"Naismith 發明籃球。","k":[["invented","發明"]]},{"id":"B25","set":"B","ch":"05","t":"T","q":"True or False: **Hockey** is Canada's official summer sport.","zq":"是非題：冰球是加拿大官方的夏季運動。","o":["True","False"],"zo":["對","錯"],"a":1,"f":1,"e":"錯。冰球是冬季國家運動；夏季是長曲棍球（lacrosse）。","k":[]},{"id":"B26","set":"B","ch":"06","t":"S","q":"Canada's system of government is **BEST** described as:","zq":"加拿大的政府制度「最好」的描述是：","o":["A federal state, a parliamentary democracy and a constitutional monarchy","A republic led by an elected president","An absolute monarchy","A single government with no provinces"],"zo":["聯邦制國家、議會民主、君主立憲","由民選總統領導的共和國","絕對君主制","沒有省份的單一政府"],"a":0,"f":0,"e":"三個關鍵字：federal state、parliamentary democracy、constitutional monarchy。","k":[["constitutional monarchy","君主立憲"],["federal state","聯邦國家"]]},{"id":"B27","set":"B","ch":"06","t":"S","q":"Who **represents the Sovereign** in Canada at the federal level?","zq":"在聯邦層級，誰「代表君主」？","o":["The Governor General","The Prime Minister","The Lieutenant Governor","The Premier"],"zo":["總督","總理","省督","省長"],"a":0,"f":0,"e":"聯邦 = Governor General（總督）；省 = Lieutenant Governor（省督）。2026 年 6 月起的總督是 Louise Arbour（第 31 任）。","k":[["represents","代表"]]},{"id":"B28","set":"B","ch":"06","t":"N","q":"Which of the following is **NOT** one of the three parts of Parliament?","zq":"下列哪一個「不是」國會的三個組成部分之一？","o":["The Supreme Court of Canada","The Sovereign","The Senate","The House of Commons"],"zo":["加拿大最高法院","君主","參議院","下議院"],"a":0,"f":0,"e":"國會 = 君主 + 參議院 + 下議院。法院屬於司法，不是國會。","k":[["parts","部分"],["Parliament","國會"]]},{"id":"B29","set":"B","ch":"06","t":"S","q":"What is the **final step** before a bill becomes law?","zq":"法案成為法律前的「最後一步」是什麼？","o":["Royal Assent, granted by the Governor General","A vote by all citizens","Approval by the Supreme Court","Signature by every premier"],"zo":["由總督給予御准（Royal Assent）","全體公民投票","最高法院批准","每位省長簽名"],"a":0,"f":0,"e":"bill = 法案。兩院通過後，總督代表君主給 Royal Assent 才成為法律。","k":[["bill","法案"],["Royal Assent","御准"]]},{"id":"B30","set":"B","ch":"06","t":"S","q":"Which areas are **shared** by the federal and provincial governments?","zq":"哪些領域由聯邦和省「共同」負責？","o":["Agriculture and immigration","Defence and currency","Education and highways","Snow removal and recycling"],"zo":["農業和移民","國防和貨幣","教育和公路","除雪和回收"],"a":0,"f":0,"e":"shared = 共享。聯邦與省共同負責：農業、移民。","k":[["shared","共同的"]]},{"id":"B31","set":"B","ch":"06","t":"C","q":"If the government **loses a confidence vote** in the House of Commons, what usually happens?","zq":"如果政府在下議院「失去信任投票」，通常會怎樣？","o":["The Prime Minister asks the Governor General to call an election","The Senate takes over the government","The King chooses a new Prime Minister himself","Nothing changes until the next fixed date"],"zo":["總理請總督宣佈選舉","參議院接管政府","國王自己挑新總理","什麼都不變，等到固定選舉日"],"a":0,"f":0,"e":"失去多數支持 → 通常舉行選舉。","k":[["confidence vote","信任投票"]]},{"id":"B32","set":"B","ch":"06","t":"T","q":"True or False: The **Prime Minister** is Canada's Head of State.","zq":"是非題：總理是加拿大的國家元首。","o":["True","False"],"zo":["對","錯"],"a":1,"f":1,"e":"錯。國家元首是君主（國王），總理是政府首腦。","k":[["Head of State","國家元首"]]},{"id":"B33","set":"B","ch":"07","t":"S","q":"An **electoral district** is also called a:","zq":"「選區」也叫做：","o":["Riding (or constituency)","Province","Municipality","Territory"],"zo":["Riding（選區）","省","市鎮","地區"],"a":0,"f":0,"e":"riding = 選區，每個選區選一位 MP。","k":[["electoral district","選區"],["riding","選區（口語）"]]},{"id":"B34","set":"B","ch":"08","t":"S","q":"\"**Due process**\" means that:","zq":"「正當程序」的意思是：","o":["The government must respect all the legal rights a person is entitled to under the law","Court cases must finish within one week","Only citizens can go to court","Police may skip the courts"],"zo":["政府必須尊重每個人依法享有的所有權利","案件必須一週內結束","只有公民可以上法院","警察可以跳過法院"],"a":0,"f":0,"e":"due process = 正當法律程序。","k":[["due process","正當程序"],["entitled to","有權享有"]]},{"id":"B35","set":"B","ch":"08","t":"N","q":"The RCMP acts as the provincial police in all provinces **EXCEPT**:","zq":"皇家騎警在所有省份擔任省警察，「除了」：","o":["Ontario and Quebec","Alberta and Manitoba","British Columbia and Nova Scotia","New Brunswick and PEI"],"zo":["安大略和魁北克","亞伯達和曼尼托巴","卑詩省和新斯科細亞","新布藍瑞克和愛德華王子島"],"a":0,"f":0,"e":"安大略有 OPP、魁北克有 Sûreté du Québec，所以 RCMP 在這兩省不當省警。","k":[["acts as","擔任"],["EXCEPT","除了"]]},{"id":"B36","set":"B","ch":"09","t":"R","q":"Canada's current red-and-white **maple leaf flag** was raised for the first time in:","zq":"加拿大現在的紅白「楓葉旗」第一次升起是在：","o":["1965","1867","1982","1921"],"zo":["1965","1867","1982","1921"],"a":0,"f":0,"e":"楓葉旗 1965 年。1921 年是紅白被定為國家顏色。","k":[["raised","升起"]]},{"id":"B37","set":"B","ch":"09","t":"S","q":"What is Canada's **ROYAL** anthem?","zq":"加拿大的「皇家」頌歌是什麼？","o":["God Save the King","O Canada","The Maple Leaf Forever","In Flanders Fields"],"zo":["天佑吾王","啊，加拿大","楓葉萬歲","在法蘭德斯戰場"],"a":0,"f":0,"e":"陷阱：National anthem（國歌）= O Canada；Royal anthem（皇家頌歌）= God Save the King。","k":[["royal","皇家的"],["anthem","頌歌、國歌"]]},{"id":"B38","set":"B","ch":"09","t":"R","q":"The **Peace Tower** on Parliament Hill was completed in memory of:","zq":"國會山莊的「和平塔」是為了紀念：","o":["The First World War","Confederation","The War of 1812","The Korean War"],"zo":["第一次世界大戰","聯邦成立","1812 年戰爭","韓戰"],"a":0,"f":0,"e":"Peace Tower 紀念一戰，內有 Memorial Chamber 和陣亡者名冊。","k":[["in memory of","紀念"]]},{"id":"B39","set":"B","ch":"09","t":"R","q":"**Victoria Day** celebrates:","zq":"「維多利亞日」慶祝：","o":["The birthday of the Sovereign (originally Queen Victoria)","The anniversary of Confederation","The end of the First World War","The founding of Quebec City"],"zo":["君主的生日（原為維多利亞女王）","聯邦成立週年","一戰結束","魁北克市建城"],"a":0,"f":0,"e":"5 月 25 日前的星期一。","k":[["celebrates","慶祝"]]},{"id":"B40","set":"B","ch":"11","t":"N","q":"Canada is bordered by three oceans. Which ocean does **NOT** border Canada?","zq":"加拿大被三個海洋包圍，哪個海洋「不」與加拿大相鄰？","o":["The Indian Ocean","The Pacific Ocean","The Atlantic Ocean","The Arctic Ocean"],"zo":["印度洋","太平洋","大西洋","北冰洋"],"a":0,"f":0,"e":"三大洋：太平洋、大西洋、北冰洋。","k":[["bordered by","被……包圍"],["ocean","海洋"]]},{"id":"B41","set":"B","ch":"11","t":"F","q":"Which was the **LAST** province to join Confederation (1949)?","zq":"哪一省「最後」加入聯邦（1949）？","o":["Newfoundland and Labrador","Prince Edward Island","British Columbia","Saskatchewan"],"zo":["紐芬蘭與拉布拉多","愛德華王子島","卑詩省","薩克其萬"],"a":0,"f":0,"e":"LAST = 最後。紐芬蘭 1949 年加入。","k":[["last","最後的"]]},{"id":"B42","set":"B","ch":"11","t":"S","q":"Which city is known as the \"**diamond capital of North America**\"?","zq":"哪個城市被稱為「北美鑽石之都」？","o":["Yellowknife","Whitehorse","Iqaluit","Halifax"],"zo":["黃刀鎮","白馬市","伊魁特","哈利法克斯"],"a":0,"f":0,"e":"Yellowknife 是西北地區首府。","k":[["diamond","鑽石"]]},{"id":"B43","set":"B","ch":"11","t":"R","q":"Canada's largest and busiest port, its gateway to the Asia-Pacific, is in:","zq":"加拿大最大、最繁忙的港口，也是通往亞太的門戶，位於：","o":["Vancouver","Halifax","Montreal","Toronto"],"zo":["溫哥華","哈利法克斯","蒙特婁","多倫多"],"a":0,"f":0,"e":"Port of Vancouver。","k":[["port","港口"],["busiest","最繁忙的"]]},{"id":"C01","set":"C","ch":"02","t":"R","q":"Which document, signed in England in 1215, is the **source** of freedoms such as habeas corpus?","zq":"哪份 1215 年在英國簽署的文件，是人身保護令等自由的「源頭」？","o":["Magna Carta (the Great Charter of Freedoms)","The Canadian Charter of Rights and Freedoms","The Constitution Act, 1982","The Royal Proclamation of 1763"],"zo":["大憲章","加拿大權利與自由憲章","1982 年憲法法案","1763 年皇家公告"],"a":0,"f":0,"e":"題目沒說 Magna Carta，而是給年份和用途反問你。1215 年 = 大憲章。","k":[["source","來源"],["habeas corpus","人身保護令"]]},{"id":"C02","set":"C","ch":"02","t":"N","q":"All of the following are fundamental freedoms protected by the Charter **EXCEPT**:","zq":"以下都是憲章保護的基本自由，「除了」哪一項？","o":["Freedom from paying taxes","Freedom of conscience and religion","Freedom of thought, belief, opinion and expression","Freedom of peaceful assembly"],"zo":["不用繳稅的自由","良心與宗教自由","思想、信仰、意見與表達自由","和平集會自由"],"a":0,"f":0,"e":"EXCEPT = 除了……以外。題目要你找「不屬於」的那一個。四大基本自由：良心與宗教、思想信仰表達（含言論與新聞）、和平集會、結社。","k":[["EXCEPT","除了（找不屬於的）"],["assembly","集會"]]},{"id":"C03","set":"C","ch":"02","t":"S","q":"Which of the following is a **RESPONSIBILITY** rather than a right?","zq":"下列哪一項是「責任」而「不是」權利？","o":["Obeying the law","Freedom of religion","Mobility rights","Official language rights"],"zo":["遵守法律","宗教自由","遷徙權","官方語言權利"],"a":0,"f":0,"e":"rather than = 而不是。宗教自由、遷徙權、語言權都是「權利」；守法是「責任」。","k":[["rather than","而不是"],["right","權利"]]},{"id":"C04","set":"C","ch":"02","t":"R","q":"Which action is an example of **protecting and enjoying our heritage and environment**?","zq":"哪個行為是「保護與享受我們的遺產和環境」的例子？","o":["Avoiding waste and pollution while protecting natural, cultural and architectural heritage","Voting only in federal elections","Joining the Canadian Forces","Learning both official languages"],"zo":["避免浪費和污染，同時保護自然、文化和建築遺產","只在聯邦選舉投票","加入加拿大軍隊","學習兩種官方語言"],"a":0,"f":0,"e":"heritage = 遺產；environment = 環境。答案重點：不浪費、不污染、保護遺產。","k":[["heritage","遺產"],["pollution","污染"]]},{"id":"C05","set":"C","ch":"02","t":"N","q":"Which of the following is **NOT** a requirement for voting in a federal election?","zq":"下列哪一項「不是」聯邦選舉投票的條件？","o":["Owning property","Being a Canadian citizen","Being at least 18 years old on election day","Being on the voters' list"],"zo":["擁有房地產","是加拿大公民","選舉日當天滿 18 歲","在選民名冊上"],"a":0,"f":0,"e":"投票三條件：公民、選舉日滿 18 歲、在選民名冊上。不需要有房產。","k":[["requirement","條件、要求"],["voters' list","選民名冊"]]},{"id":"C06","set":"C","ch":"03","t":"N","q":"Which group is **NOT** one of the three distinct groups of Aboriginal peoples in Canada?","zq":"哪一群「不是」加拿大原住民的三個群體之一？","o":["Acadians","First Nations","Inuit","Métis"],"zo":["阿卡迪亞人","第一民族","因紐特人","梅蒂斯人"],"a":0,"f":0,"e":"Acadians（阿卡迪亞人）是法國殖民者的後代，不是原住民。","k":[["distinct","不同的、各自獨立的"],["Aboriginal","原住民的"]]},{"id":"C07","set":"C","ch":"03","t":"R","q":"Which people are **descendants** of French colonists who began settling in the Maritime provinces in 1604?","zq":"哪一群人是 1604 年開始定居在濱海省份的法國殖民者「後代」？","o":["Acadians","Québécois","Métis","United Empire Loyalists"],"zo":["阿卡迪亞人","魁北克人","梅蒂斯人","效忠派"],"a":0,"f":0,"e":"Maritime（濱海省份）＋1604 → Acadians。","k":[["descendants","後代"],["colonists","殖民者"]]},{"id":"C08","set":"C","ch":"03","t":"F","q":"Which is Canada's **only officially bilingual** province?","zq":"加拿大「唯一」的官方雙語省份是？","o":["New Brunswick","Quebec","Ontario","Manitoba"],"zo":["新布藍瑞克","魁北克","安大略","曼尼托巴"],"a":0,"f":0,"e":"陷阱：很多人選魁北克，但魁北克官方語言只有法文。唯一官方雙語省 = New Brunswick。","k":[["bilingual","雙語的"],["only","唯一"]]},{"id":"C09","set":"C","ch":"03","t":"W","q":"Which statement about **residential schools** is **TRUE**?","zq":"關於「寄宿學校」，哪一句是「正確」的？","o":["They were set up to educate and assimilate Aboriginal children, and Ottawa formally apologized in 2008","They were private universities for new immigrants","Attendance was always voluntary","They were run by the Inuit to teach French"],"zo":["目的是教育並同化原住民兒童，聯邦政府在 2008 年正式道歉","是給新移民讀的私立大學","一直都是自願入學","由因紐特人開辦教法語"],"a":0,"f":0,"e":"assimilate = 同化。寄宿學校讓原住民孩子離開家庭、禁止說母語，2008 年政府正式道歉。","k":[["assimilate","同化"],["formally apologized","正式道歉"]]},{"id":"C10","set":"C","ch":"04","t":"R","q":"In 1497, who was the **first** to draw a map of Canada's East Coast?","zq":"1497 年，誰「第一個」畫出加拿大東岸的地圖？","o":["John Cabot","Jacques Cartier","Samuel de Champlain","Henry Hudson"],"zo":["約翰・卡伯特","雅克・卡蒂亞","尚普蘭","亨利・哈德遜"],"a":0,"f":0,"e":"1497 + 地圖 = John Cabot（為英國航行的義大利人）。","k":[["coast","海岸"]]},{"id":"C11","set":"C","ch":"04","t":"R","q":"Who is known as the **founder** of Quebec City (1608)?","zq":"誰被稱為魁北克市（1608 年）的「創建者」？","o":["Samuel de Champlain","Jacques Cartier","Louis-Joseph Papineau","Count Frontenac"],"zo":["尚普蘭","卡蒂埃","帕皮諾","弗隆特納克伯爵"],"a":0,"f":0,"e":"Champlain 1608 年建立魁北克城堡，被稱為「新法蘭西之父」。","k":[["founder","創建者"]]},{"id":"C12","set":"C","ch":"04","t":"S","q":"The **United Empire Loyalists** were:","zq":"「聯合帝國效忠派」是：","o":["People who stayed loyal to the Crown and came to Canada from the American colonies after 1776","French soldiers who stayed after 1759","The first settlers of Nunavut","Members of the first Parliament in 1867"],"zo":["忠於英國王室、1776 年後從美洲殖民地移居加拿大的人","1759 年後留下的法國士兵","努納福特最早的居民","1867 年第一屆國會議員"],"a":0,"f":0,"e":"loyal to the Crown = 忠於王室。美國獨立後，不想脫離英國的人搬到加拿大。","k":[["loyal","忠誠的"],["colonies","殖民地"]]},{"id":"C13","set":"C","ch":"04","t":"F","q":"Which was the **first** province in the British Empire to move toward **abolishing slavery** (1793)?","zq":"哪一個是大英帝國中「第一個」走向「廢除奴隸制」的省（1793）？","o":["Upper Canada","Lower Canada","Nova Scotia","Newfoundland"],"zo":["上加拿大","下加拿大","新斯科細亞","紐芬蘭"],"a":0,"f":0,"e":"1793 年上加拿大副總督 John Graves Simcoe 推動，成為大英帝國第一個走向廢奴的省。","k":[["abolish","廢除"],["slavery","奴隸制"]]},{"id":"C14","set":"C","ch":"04","t":"W","q":"Which statement about the **War of 1812** is **TRUE**?","zq":"關於「1812 年戰爭」，哪一句「正確」？","o":["The United States invaded Canada and was defeated","Canada invaded the United States and captured Boston","France invaded Canada to take back Quebec","It ended with Canada joining the United States"],"zo":["美國入侵加拿大並被擊敗","加拿大入侵美國並攻下波士頓","法國入侵加拿大想奪回魁北克","結果加拿大加入美國"],"a":0,"f":0,"e":"美國入侵，被英軍、加拿大民兵和原住民擊退，確保加拿大不會併入美國。","k":[["invaded","入侵"]]},{"id":"C15","set":"C","ch":"04","t":"W","q":"Why did reformers in Upper and Lower Canada **rebel** in 1837–38?","zq":"1837–38 年上、下加拿大的改革者為什麼「起義」？","o":["They wanted responsible government / more democracy","They wanted to join the United States","They wanted to end the fur trade","They wanted to restore French rule"],"zo":["他們想要責任政府（更民主）","想加入美國","想結束毛皮貿易","想恢復法國統治"],"a":0,"f":0,"e":"rebel = 起義。改革者認為民主進展太慢，要求責任政府。","k":[["rebel","起義、反叛"],["reformers","改革者"]]},{"id":"C16","set":"C","ch":"04","t":"R","q":"Who was the **first head** of a responsible government in the Canadas, in 1849?","zq":"1849 年，誰是加拿大（聯合省）責任政府的「第一位領袖」？","o":["Sir Louis-Hippolyte La Fontaine","Sir John A. Macdonald","Joseph Howe","Lord Durham"],"zo":["拉封丹爵士","麥克唐納","約瑟夫・豪","德倫勳爵"],"a":0,"f":0,"e":"La Fontaine，民主與法語權利的捍衛者。","k":[["head","領袖、首長"]]},{"id":"C17","set":"C","ch":"04","t":"S","q":"The \"**Fathers of Confederation**\" were:","zq":"「聯邦之父」是：","o":["Representatives who worked together from 1864 to 1867 to establish Canada","The first Governors General","French explorers of the 1600s","Soldiers who fought at Vimy Ridge"],"zo":["1864–1867 年共同努力建立加拿大的代表們","最早的總督們","1600 年代的法國探險家","在維米嶺作戰的士兵"],"a":0,"f":0,"e":"Fathers of Confederation 是一群建立加拿大的代表，不是真的「爸爸」。","k":[["representatives","代表"],["establish","建立"]]},{"id":"C18","set":"C","ch":"04","t":"S","q":"What was \"**Dominion Day**\" renamed?","zq":"「自治領日」後來改名為什麼？","o":["Canada Day","Victoria Day","Remembrance Day","Thanksgiving"],"zo":["加拿大國慶日","維多利亞日","陣亡將士紀念日","感恩節"],"a":0,"f":0,"e":"7 月 1 日原稱 Dominion Day，1982 年改名 Canada Day。","k":[["renamed","改名"]]},{"id":"C19","set":"C","ch":"04","t":"C","q":"British Columbia agreed to join Confederation in 1871 **because** Ottawa promised to:","zq":"卑詩省在 1871 年同意加入聯邦，「是因為」渥太華承諾要：","o":["Build a railway to the West Coast","Make Vancouver the capital","Remove all taxes in B.C.","Give B.C. its own army"],"zo":["建一條通到西岸的鐵路","讓溫哥華當首都","取消卑詩省所有稅收","給卑詩省自己的軍隊"],"a":0,"f":0,"e":"承諾建橫貫鐵路 → Canadian Pacific Railway，1885 年完工（Last Spike）。","k":[["promised","承諾"],["railway","鐵路"]]},{"id":"C20","set":"C","ch":"04","t":"R","q":"Why do Canadians wear a **red poppy** on November 11?","zq":"加拿大人為什麼在 11 月 11 日戴「紅色罌粟花」？","o":["To remember the sacrifice of those who served and died for Canada","To celebrate the harvest","To mark the King's birthday","To celebrate Confederation"],"zo":["紀念為加拿大服役與犧牲的人","慶祝豐收","慶祝國王生日","慶祝聯邦成立"],"a":0,"f":0,"e":"Remembrance Day（陣亡將士紀念日），1918 年 11 月 11 日一戰停戰。","k":[["poppy","罌粟花"],["remember","紀念"]]},{"id":"C21","set":"C","ch":"04","t":"F","q":"Who was the **first woman** elected to the House of Commons (1921)?","zq":"誰是「第一位」當選下議院議員的女性（1921）？","o":["Agnes Macphail","Emily Stowe","Laura Secord","Thérèse Casgrain"],"zo":["艾格妮絲・麥克費爾","艾蜜莉・斯托","蘿拉・塞科德","卡斯格蘭"],"a":0,"f":0,"e":"Agnes Macphail = 第一位女議員；Emily Stowe = 第一位在加拿大行醫的女性。","k":[["elected","當選"]]},{"id":"C22","set":"C","ch":"04","t":"S","q":"The period of rapid change in **Quebec** in the 1960s is known as:","zq":"1960 年代「魁北克」快速變革的時期被稱為：","o":["The Quiet Revolution","The Great Upheaval","The Red River Rebellion","Confederation"],"zo":["寧靜革命","大動盪","紅河起義","聯邦"],"a":0,"f":0,"e":"Quiet Revolution = 寧靜革命。","k":[["rapid","快速的"]]},{"id":"C23","set":"C","ch":"04","t":"T","q":"True or False: The Charter of Rights and Freedoms became part of the Constitution in **1867**.","zq":"是非題：權利與自由憲章在 1867 年成為憲法的一部分。","o":["True","False"],"zo":["對","錯"],"a":1,"f":1,"e":"錯。是 1982 年。","k":[["became part of","成為……的一部分"]]},{"id":"C24","set":"C","ch":"05","t":"R","q":"Which trophy is awarded to the champion of **Canadian football**?","zq":"哪一座獎盃頒給「加拿大式足球」冠軍？","o":["The Grey Cup","The Stanley Cup","The Victoria Cross","The Memorial Cup"],"zo":["格雷杯","史丹利杯","維多利亞十字勳章","紀念杯"],"a":0,"f":0,"e":"Grey Cup（Lord Grey 捐贈）= 足球；Stanley Cup（Lord Stanley 捐贈）= 冰球。兩人都是總督。","k":[["trophy","獎盃"],["champion","冠軍"]]},{"id":"C25","set":"C","ch":"05","t":"R","q":"**Sir Frederick Banting and Charles Best** are known for:","zq":"班廷爵士與貝斯特以什麼聞名？","o":["Discovering insulin to treat diabetes","Inventing the telephone","Inventing the snowmobile","Building the first railway"],"zo":["發現治療糖尿病的胰島素","發明電話","發明雪地摩托車","建造第一條鐵路"],"a":0,"f":0,"e":"insulin = 胰島素。電話是 Alexander Graham Bell；雪地摩托車是 Bombardier。","k":[["insulin","胰島素"],["diabetes","糖尿病"]]},{"id":"C26","set":"C","ch":"06","t":"S","q":"Who is Canada's **Head of State**?","zq":"誰是加拿大的「國家元首」？","o":["The Sovereign (the King)","The Prime Minister","The Governor General","The Chief Justice"],"zo":["君主（國王）","總理","總督","首席大法官"],"a":0,"f":0,"e":"最大陷阱！Head of State（國家元首）= 國王；Head of Government（政府首腦）= 總理。","k":[["Head of State","國家元首"],["Sovereign","君主"]]},{"id":"C27","set":"C","ch":"06","t":"S","q":"In each province, the Sovereign is represented by the:","zq":"在每個省，君主由誰代表？","o":["Lieutenant Governor","Premier","Governor General","Mayor"],"zo":["省督","省長","總督","市長"],"a":0,"f":0,"e":"Lieutenant Governor（省督）由總督依總理建議任命。不要和 Premier（省長）搞混。","k":[["Lieutenant Governor","省督"]]},{"id":"C28","set":"C","ch":"06","t":"S","q":"**Senators** are:","zq":"「參議員」是：","o":["Appointed by the Governor General on the advice of the Prime Minister, and serve until age 75","Elected by the people every four years","Appointed for life by the King","Chosen by the provincial premiers"],"zo":["由總督依總理建議任命，任職到 75 歲","每四年由人民選出","由國王終身任命","由各省省長選出"],"a":0,"f":0,"e":"陷阱：參議員不是選出來的，是「任命」的，做到 75 歲。","k":[["appointed","任命"],["on the advice of","依照……的建議"]]},{"id":"C29","set":"C","ch":"06","t":"S","q":"Which of the following is a **PROVINCIAL** responsibility?","zq":"下列哪一項是「省政府」的職責？","o":["Education","National defence","Currency","Citizenship"],"zo":["教育","國防","貨幣","公民身份"],"a":0,"f":0,"e":"省：教育、醫療、天然資源、公路、財產與民權。聯邦：國防、外交、貨幣、刑法、公民身份。","k":[["defence","國防"],["currency","貨幣"]]},{"id":"C30","set":"C","ch":"06","t":"C","q":"You want to complain about **snow removal and garbage collection** on your street. Which level of government is responsible?","zq":"你想投訴街上的「除雪和垃圾收集」，該找哪一級政府？","o":["Municipal (local) government","Federal government","Provincial government","The Senate"],"zo":["市政府","聯邦政府","省政府","參議院"],"a":0,"f":0,"e":"市政府負責：除雪、回收、垃圾、地方警察、消防、公共交通等。","k":[["municipal","市政的"],["snow removal","除雪"]]},{"id":"C31","set":"C","ch":"06","t":"S","q":"Which party usually forms the **Official Opposition**?","zq":"哪一個政黨通常成為「官方反對黨」？","o":["The party with the second-most seats in the House of Commons","The party with the fewest seats","The party chosen by the Senate","All parties except the governing party, together"],"zo":["下議院席次第二多的政黨","席次最少的政黨","參議院選的政黨","除執政黨外所有政黨合起來"],"a":0,"f":0,"e":"second-most = 第二多。","k":[["Official Opposition","官方反對黨"],["seats","席次"]]},{"id":"C32","set":"C","ch":"06","t":"T","q":"True or False: Senators are **elected** by the people of their province.","zq":"是非題：參議員由該省人民選出。","o":["True","False"],"zo":["對","錯"],"a":1,"f":1,"e":"錯。參議員是「任命」的，不是選出來的。","k":[["elected","選出"]]},{"id":"C33","set":"C","ch":"07","t":"S","q":"Federal elections must be held:","zq":"聯邦選舉必須在何時舉行？","o":["On the third Monday in October every four years after the last general election","Every two years on July 1","Whenever the Senate decides","Every five years on Remembrance Day"],"zo":["上次大選後每四年的十月第三個星期一","每兩年的 7 月 1 日","參議院決定時","每五年的陣亡將士紀念日"],"a":0,"f":0,"e":"Discover Canada：每四年的十月第三個星期一（但政府倒閣時會提早）。","k":[["held","舉行"]]},{"id":"C34","set":"C","ch":"07","t":"C","q":"Election day is coming, but you did **NOT** receive a voter information card. What should you do?","zq":"選舉快到了，你「沒有」收到選民資訊卡，該怎麼辦？","o":["Contact Elections Canada / your local elections office","You cannot vote in this election","Ask your MP to vote for you","Wait until the next election"],"zo":["聯絡加拿大選舉局或本地選舉辦公室","你不能在這次選舉投票","請你的議員代你投票","等下次選舉"],"a":0,"f":0,"e":"沒收到卡不代表不能投票，聯絡選舉局確認登記即可。","k":[["voter information card","選民資訊卡"]]},{"id":"C35","set":"C","ch":"08","t":"F","q":"Which is the **HIGHEST** court in Canada?","zq":"加拿大「最高」的法院是？","o":["The Supreme Court of Canada","The Federal Court","The Provincial Court","The Court of Appeal"],"zo":["加拿大最高法院","聯邦法院","省法院","上訴法院"],"a":0,"f":0,"e":"Supreme Court of Canada 是最終上訴法院。","k":[["highest","最高的"]]},{"id":"C36","set":"C","ch":"08","t":"C","q":"A police officer treated you unfairly. What can you do?","zq":"警察對你不公平，你可以怎麼做？","o":["Make a complaint to the police organization or oversight body","Nothing — you can never question police","Refuse to obey any laws","Ask your employer to fire the officer"],"zo":["向警察機構或監督單位投訴","什麼都不能做，不能質疑警察","拒絕遵守所有法律","請你的老闆開除警察"],"a":0,"f":0,"e":"警察也要守法，可以投訴。","k":[["complaint","投訴"],["unfairly","不公平地"]]},{"id":"C37","set":"C","ch":"09","t":"S","q":"Canada's motto \"**A Mari Usque Ad Mare**\" means:","zq":"加拿大的格言「A Mari Usque Ad Mare」意思是：","o":["From sea to sea","True north strong and free","Peace, order and good government","Our home and native land"],"zo":["從海到海","真正的北方，強大又自由","和平、秩序與良好政府","我們的家園與故土"],"a":0,"f":0,"e":"拉丁文，from sea to sea。","k":[["motto","格言"]]},{"id":"C38","set":"C","ch":"09","t":"R","q":"The **fleur-de-lys** appears on the flag of which province?","zq":"「鳶尾花（fleur-de-lys）」出現在哪一省的旗幟上？","o":["Quebec","New Brunswick","Nova Scotia","Manitoba"],"zo":["魁北克","新布藍瑞克","新斯科細亞","曼尼托巴"],"a":0,"f":0,"e":"fleur-de-lys 來自法國王室，魁北克省旗。","k":[["appears","出現"]]},{"id":"C39","set":"C","ch":"09","t":"F","q":"What is the **highest honour** available to Canadians, awarded for the most conspicuous bravery?","zq":"加拿大人能獲得的「最高榮譽」、頒給最顯著英勇行為的是？","o":["The Victoria Cross","The Order of Canada","The Stanley Cup","The Grey Cup"],"zo":["維多利亞十字勳章","加拿大勳章","史丹利杯","格雷杯"],"a":0,"f":0,"e":"Victoria Cross (V.C.)。","k":[["honour","榮譽"],["bravery","英勇"]]},{"id":"C40","set":"C","ch":"09","t":"R","q":"Who chose **Ottawa** as the capital in 1857?","zq":"1857 年，誰選擇「渥太華」作為首都？","o":["Queen Victoria","Sir John A. Macdonald","Samuel de Champlain","Lord Durham"],"zo":["維多利亞女王","麥克唐納","尚普蘭","德倫勳爵"],"a":0,"f":0,"e":"Queen Victoria 選的，當時是 1857 年（聯邦前）。","k":[["capital","首都"]]},{"id":"C41","set":"C","ch":"10","t":"F","q":"Most Canadians work in which type of industry?","zq":"「大多數」加拿大人在哪一類產業工作？","o":["Service industries","Natural resource industries","Manufacturing industries","Fishing"],"zo":["服務業","天然資源業","製造業","漁業"],"a":0,"f":0,"e":"超過 75% 的人在服務業。三大產業：服務、製造、天然資源。","k":[["industry","產業"]]},{"id":"C42","set":"C","ch":"11","t":"F","q":"More than **one-third** of Canadians live in which province?","zq":"超過「三分之一」的加拿大人住在哪一省？","o":["Ontario","Quebec","British Columbia","Alberta"],"zo":["安大略","魁北克","卑詩省","亞伯達"],"a":0,"f":0,"e":"one-third = 三分之一。安大略人口最多。","k":[["one-third","三分之一"]]},{"id":"C43","set":"C","ch":"11","t":"R","q":"Which territory was created in **1999** from part of the Northwest Territories?","zq":"哪個地區在「1999 年」從西北地區劃分出來？","o":["Nunavut","Yukon","Labrador","Manitoba"],"zo":["努納福特","育空","拉布拉多","曼尼托巴"],"a":0,"f":0,"e":"Nunavut = our land，首府 Iqaluit。","k":[["territory","地區（領地）"]]},{"id":"C44","set":"C","ch":"11","t":"N","q":"Which province is **NOT** a Prairie province?","zq":"哪一省「不是」草原省份？","o":["British Columbia","Manitoba","Saskatchewan","Alberta"],"zo":["卑詩省","曼尼托巴","薩克其萬","亞伯達"],"a":0,"f":0,"e":"草原三省：曼尼托巴、薩克其萬、亞伯達。","k":[["Prairie","草原"]]},{"id":"C45","set":"C","ch":"11","t":"T","q":"True or False: Nunavut became a territory in **1999**.","zq":"是非題：努納福特在 1999 年成為地區。","o":["True","False"],"zo":["對","錯"],"a":0,"f":1,"e":"對。","k":[]},{"id":"D01","set":"D","ch":"02","t":"N","q":"Which of the following is **NOT** covered by mobility rights?","zq":"下列哪一項「不屬於」遷徙權？","o":["Owning property in another country","Living anywhere in Canada","Working anywhere in Canada","Entering and leaving Canada freely"],"zo":["在別的國家擁有房地產","在加拿大任何地方居住","在加拿大任何地方工作","自由出入加拿大"],"a":0,"f":0,"e":"遷徙權指的是在加拿大境內居住、工作，以及自由出入境——不包含在國外置產這件事。","k":[["mobility rights","遷徙權"]]},{"id":"D02","set":"D","ch":"02","t":"R","q":"Which document is **quoted in the Oath of Citizenship** as recognizing Aboriginal and treaty rights?","zq":"入籍誓詞裡提到「承認並確認」原住民與條約權利的是哪一份文件？","o":["The Constitution, including the Charter","The Quebec Act, 1774","Magna Carta","The Immigration Act"],"zo":["憲法，包含憲章","1774 年魁北克法案","大憲章","移民法"],"a":0,"f":0,"e":"誓詞原文：will faithfully observe the laws of Canada, **including the Constitution**, which recognizes and affirms the Aboriginal and treaty rights of First Nations, Inuit and Métis peoples。","k":[["recognizes and affirms","承認並確認"]]},{"id":"D03","set":"D","ch":"02","t":"T","q":"True or False: The Canadian Constitution includes the Charter of Rights and Freedoms.","zq":"是非題：加拿大憲法包含《權利與自由憲章》。","o":["True","False"],"zo":["對","錯"],"a":0,"f":1,"e":"對。1982 年的憲法把《權利與自由憲章》寫進去了。","k":[["Constitution","憲法"]]},{"id":"D04","set":"D","ch":"02","t":"R","q":"\"Habeas corpus\" comes from which legal tradition?","zq":"「Habeas corpus」源自哪個法律傳統？","o":["English common law","French civil law","Roman law","Indigenous customary law"],"zo":["英國普通法","法國民法","羅馬法","原住民習慣法"],"a":0,"f":0,"e":"加拿大法律來自英國憲政傳統、英國普通法、法國民法（用在魁北克）三個源頭；人身保護令來自英國普通法。","k":[["common law","普通法"]]},{"id":"D05","set":"D","ch":"02","t":"S","q":"What is the term for the idea that no one, including the government, is above the law?","zq":"「沒有人，包括政府，凌駕於法律之上」這個概念叫做什麼？","o":["The rule of law","Due process","Presumption of innocence","Responsible government"],"zo":["法治","正當程序","無罪推定","責任政府"],"a":0,"f":0,"e":"法治（Rule of Law）：所有人都受法律約束，沒有人例外。","k":[["rule of law","法治"]]},{"id":"D06","set":"D","ch":"03","t":"S","q":"The National Day for Truth and Reconciliation is observed on which date?","zq":"「真相與和解日」訂在哪一天？","o":["September 30","November 11","July 1","June 21"],"zo":["9 月 30 日","11 月 11 日","7 月 1 日","6 月 21 日"],"a":0,"f":0,"e":"9 月 30 日，紀念寄宿學校的受害者與倖存者。","k":[["observed","訂在"]]},{"id":"D07","set":"D","ch":"03","t":"R","q":"Who did the government apologize to in **2008**?","zq":"政府在「2008 年」向誰道歉？","o":["Residential school survivors","Japanese Canadians","Chinese Canadians (Head Tax)","Acadians"],"zo":["寄宿學校倖存者","日裔加拿大人","華人（人頭稅）","阿卡迪亞人"],"a":0,"f":0,"e":"2008 年，總理向寄宿學校的原住民倖存者正式道歉。","k":[["residential school","寄宿學校"]]},{"id":"D08","set":"D","ch":"03","t":"C","q":"A newcomer keeps celebrating her own culture's festivals while also joining Canadian community events. Is this in line with Canadian values?","zq":"一位新移民既慶祝自己文化的節日，也參加加拿大社區活動，這符合加拿大的價值觀嗎？","o":["Yes — respecting diversity while sharing in community life is exactly what multiculturalism means","No — she must give up her own traditions","No — only citizens may join community events","Only if her festival falls on a Canadian holiday"],"zo":["是的——尊重多元又融入社區生活，正是多元文化的意義","不行——她必須放棄自己的傳統","不行——只有公民可以參加社區活動","只有她的節日剛好是加拿大假日才可以"],"a":0,"f":0,"e":"多元文化不是要求同化，而是在共同生活裡保留並尊重各自的文化。","k":[["multiculturalism","多元文化"]]},{"id":"D09","set":"D","ch":"03","t":"N","q":"Which of the following is **NOT** true about official-language minority communities?","zq":"關於官方語言少數族群，下列哪一項「不正確」？","o":["They exist only in Quebec","They have a constitutional right to education in their own official language","They can be English-speaking or French-speaking depending on the province","Their rights are protected under the Charter"],"zo":["只存在於魁北克","他們有憲法保障的官方語言教育權","依省份不同，可以是英語或法語族群","他們的權利受憲章保護"],"a":0,"f":0,"e":"官方語言少數族群在每個省都存在——魁北克的英語族群、其他省的法語族群，都受憲章的少數語言教育權保障。","k":[["minority","少數"]]},{"id":"D10","set":"D","ch":"04","t":"F","q":"What is the capital of Yukon?","zq":"育空地區的首府是哪裡？","o":["Whitehorse","Yellowknife","Iqaluit","Dawson City"],"zo":["白馬市","黃刀鎮","伊魁特","道森市"],"a":0,"f":0,"e":"白馬市是育空地區首府；黃刀鎮是西北地區首府；伊魁特是努納福特首府。","k":[["capital","首府"]]},{"id":"D11","set":"D","ch":"04","t":"F","q":"What is the capital of Newfoundland and Labrador?","zq":"紐芬蘭與拉布拉多省的首府是哪裡？","o":["St. John's","Halifax","Charlottetown","Fredericton"],"zo":["聖約翰斯","哈利法克斯","夏洛特敦","弗雷德里克頓"],"a":0,"f":0,"e":"聖約翰斯，1949 年加入聯邦，是最後一個加入的省。","k":[["capital","首府"]]},{"id":"D12","set":"D","ch":"04","t":"R","q":"Donald Smith (Lord Strathcona) is remembered for driving the **last spike** of which railway, in 1885?","zq":"唐納德・史密斯（史特拉斯科納勳爵）1885 年敲下最後一根道釘，完成了哪條鐵路？","o":["The Canadian Pacific Railway","The Grand Trunk Railway","The Underground Railroad","The Trans-Canada Highway"],"zo":["加拿大太平洋鐵路","大幹線鐵路","地下鐵路","橫加公路"],"a":0,"f":0,"e":"1885 年 11 月 7 日，CPR 董事唐納德・史密斯敲下最後一根道釘，象徵國家統一。","k":[["last spike","最後一根道釘"]]},{"id":"D13","set":"D","ch":"04","t":"R","q":"In which year did Ottawa apologize for the **Chinese Head Tax**, and under which Prime Minister?","zq":"渥太華為「華人人頭稅」道歉是哪一年？哪位總理？","o":["2006, Stephen Harper","1988, Brian Mulroney","2008, Stephen Harper","1997, Jean Chrétien"],"zo":["2006 年，史蒂芬・哈珀","1988 年，布萊恩・穆隆尼","2008 年，史蒂芬・哈珀","1997 年，讓・克雷蒂安"],"a":0,"f":0,"e":"2006 年，總理史蒂芬・哈珀正式為人頭稅道歉；2008 年道歉的對象是寄宿學校倖存者。","k":[["Head Tax","人頭稅"]]},{"id":"D14","set":"D","ch":"04","t":"N","q":"Which of the following did **NOT** join Confederation in the years 1870–1873?","zq":"下列哪一項「不是」1870 到 1873 年間加入聯邦的？","o":["Newfoundland and Labrador","Manitoba","British Columbia","Prince Edward Island"],"zo":["紐芬蘭與拉布拉多","曼尼托巴","卑詩省","愛德華王子島"],"a":0,"f":0,"e":"紐芬蘭與拉布拉多是 1949 年才加入的，遠比這一批晚。曼尼托巴 1870、卑詩省 1871、愛德華王子島 1873。","k":[["Confederation","聯邦"]]},{"id":"D15","set":"D","ch":"04","t":"R","q":"What was created in 1873, one year before the North West Mounted Police's first major mission, to help keep peace in the West?","zq":"（換句話說）西北騎警成立的年份，用來在西部維持治安並與第一民族談判的機構是？","o":["The North West Mounted Police","The Royal Canadian Navy","The Supreme Court of Canada","The Senate"],"zo":["西北騎警","加拿大皇家海軍","加拿大最高法院","參議院"],"a":0,"f":0,"e":"1873 年成立西北騎警（NWMP），也就是今天皇家騎警（RCMP）的前身。","k":[["keep peace","維持治安"]]},{"id":"D16","set":"D","ch":"04","t":"F","q":"Which province was the **birthplace of Confederation**, home to the 1864 conference?","zq":"哪一省是「聯邦的誕生地」，1864 年的會議在那裡舉行？","o":["Prince Edward Island","Nova Scotia","New Brunswick","Ontario"],"zo":["愛德華王子島","新斯科細亞","新布藍瑞克","安大略"],"a":0,"f":0,"e":"1864 年夏洛特敦會議（Charlottetown Conference）在愛德華王子島舉行。","k":[["birthplace","誕生地"]]},{"id":"D17","set":"D","ch":"05","t":"R","q":"Which organization did Canada form with the United States for continental air defence?","zq":"加拿大與美國共同組成哪個機構，負責北美的航太防禦？","o":["NORAD","NATO","NAFTA","G7"],"zo":["北美航太防禦司令部","北大西洋公約組織","北美自由貿易協定","七大工業國"],"a":0,"f":0,"e":"NORAD＝North American Aerospace Defence Command，加美共同的航太防禦司令部；NATO 則是更大範圍的軍事同盟。","k":[["NORAD","北美航太防禦司令部"]]},{"id":"D18","set":"D","ch":"05","t":"W","q":"Which statement about James Naismith is **TRUE**?","zq":"關於詹姆斯・奈史密斯，哪一句「正確」？","o":["He invented basketball in 1891","He discovered insulin","He invented the telephone","He led the Marathon of Hope"],"zo":["他在 1891 年發明了籃球","他發現了胰島素","他發明了電話","他發起了希望馬拉松"],"a":0,"f":0,"e":"加拿大人 James Naismith 於 1891 年發明籃球。","k":[["invented","發明"]]},{"id":"D19","set":"D","ch":"05","t":"F","q":"The Group of Seven is best known for their contribution to which field?","zq":"「七人畫派」以哪個領域的貢獻最為人知？","o":["Landscape painting","Classical music","Architecture","Film-making"],"zo":["風景畫","古典音樂","建築","電影製作"],"a":0,"f":0,"e":"七人畫派是加拿大最著名的風景畫家團體，1920 年成立。","k":[["landscape painting","風景畫"]]},{"id":"D20","set":"D","ch":"05","t":"R","q":"Terry Fox's \"Marathon of Hope\" was meant to raise money for:","zq":"泰瑞・福克斯的「希望馬拉松」是為了替什麼募款？","o":["Cancer research","Building schools","Refugee resettlement","Building hospitals in the North"],"zo":["癌症研究","蓋學校","難民安置","在北方蓋醫院"],"a":0,"f":0,"e":"1980 年泰瑞・福克斯因癌症失去一條腿，展開橫跨加拿大的希望馬拉松，為癌症研究募款。","k":[["cancer research","癌症研究"]]},{"id":"D21","set":"D","ch":"06","t":"S","q":"Which stage of a bill involves studying it **clause by clause**?","zq":"法案的哪一個階段是「逐條」審議？","o":["Committee Stage","First Reading","Royal Assent","Second Reading"],"zo":["委員會階段","一讀","御准","二讀"],"a":0,"f":0,"e":"委員會階段（Committee Stage）逐條審議法案；二讀是辯論原則，一讀只是印製宣讀。","k":[["clause by clause","逐條"]]},{"id":"D22","set":"D","ch":"06","t":"N","q":"Which of the following is **NOT** one of the seven stages a bill goes through before becoming law?","zq":"下列哪一項「不是」法案成為法律前的七個階段之一？","o":["Presidential veto","First Reading","Committee Stage","Royal Assent"],"zo":["總統否決","一讀","委員會階段","御准"],"a":0,"f":0,"e":"加拿大是君主立憲國家，沒有「總統否決」這種東西；最後一步是總督代表君主給予御准。","k":[["veto","否決"]]},{"id":"D23","set":"D","ch":"06","t":"R","q":"Who becomes Prime Minister after a federal election?","zq":"聯邦選舉後，誰會成為總理？","o":["The leader of the party with the most seats in the House of Commons","The person with the most personal votes nationwide","The leader chosen by the Senate","Whoever the outgoing Prime Minister names as successor"],"zo":["下議院席次最多政黨的領袖","全國個人得票最多的人","參議院選出的領袖","由卸任總理指定的繼任者"],"a":0,"f":0,"e":"下議院席次最多政黨的領袖，會被總督邀請組閣、出任總理。","k":[["most seats","席次最多"]]},{"id":"D24","set":"D","ch":"06","t":"W","q":"Which statement about how a Prime Minister is chosen is **TRUE**?","zq":"關於總理如何產生，哪一句「正確」？","o":["The Governor General invites the leader of the party with the most seats to form government","Canadians vote directly for the Prime Minister on the ballot","The King personally selects the Prime Minister without advice","The Supreme Court appoints the Prime Minister"],"zo":["總督邀請席次最多政黨的領袖組閣","加拿大人在選票上直接投給總理","國王親自挑選總理，不需建議","最高法院任命總理"],"a":0,"f":0,"e":"加拿大人投票選的是自己選區的 MP，總理是眾議院席次最多政黨的領袖，由總督邀請組閣。","k":[["invites","邀請"]]},{"id":"D25","set":"D","ch":"06","t":"S","q":"Which level of government is responsible for education and health care?","zq":"教育與醫療是哪一級政府的職責？","o":["Provincial government","Federal government","Municipal government","The Senate"],"zo":["省政府","聯邦政府","市政府","參議院"],"a":0,"f":0,"e":"教育、醫療、天然資源、公路是省政府管的；國防、外交、貨幣、刑法是聯邦的。","k":[["provincial","省的"]]},{"id":"D26","set":"D","ch":"06","t":"S","q":"A minority government is one where the governing party:","zq":"「少數政府」指的是執政黨處於什麼狀態？","o":["Holds less than half the seats in the House of Commons","Holds more than half the seats","Has no seats at all","Controls the Senate but not the House"],"zo":["在下議院席次不到一半","在下議院席次過半","完全沒有席次","控制參議院但不控制下議院"],"a":0,"f":0,"e":"席次不到一半＝少數政府；過半＝多數政府。","k":[["minority","少數"]]},{"id":"D27","set":"D","ch":"07","t":"N","q":"Which of the following is **NOT** required to vote in a federal election?","zq":"下列哪一項「不是」聯邦選舉投票的必要條件？","o":["Owning a home","Being a Canadian citizen","Being 18 or older on election day","Being on the voters' list"],"zo":["擁有自己的房子","是加拿大公民","選舉日當天滿 18 歲","在選民名冊上"],"a":0,"f":0,"e":"投票只需要公民身分、年滿 18、在選民名冊上；不需要有房產。","k":[["required","必要"]]},{"id":"D28","set":"D","ch":"07","t":"S","q":"At the polling station, how do you mark your ballot?","zq":"在投票站，你怎麼標記選票？","o":["Mark an X beside your chosen candidate","Sign your name beside the candidate","Circle the party logo","Write a short essay explaining your choice"],"zo":["在你選的候選人旁畫 X","在候選人旁簽名","圈選政黨標誌","寫一小段說明理由"],"a":0,"f":0,"e":"在候選人旁的圓圈畫 X，摺好交給工作人員。","k":[["mark an X","畫 X"]]},{"id":"D29","set":"D","ch":"07","t":"W","q":"Which statement about voting in Canada is **TRUE**?","zq":"關於加拿大投票，哪一句「正確」？","o":["Permanent residents cannot vote in federal elections","Only people born in Canada can vote","You must own property to vote","Voting is legally compulsory in Canada"],"zo":["永久居民不能在聯邦選舉投票","只有在加拿大出生的人可以投票","必須有房產才能投票","加拿大法律規定必須投票"],"a":0,"f":0,"e":"投票是公民才有的權利與責任，永久居民不可以投聯邦選舉；加拿大也沒有強制投票的法律。","k":[["permanent resident","永久居民"]]},{"id":"D30","set":"D","ch":"08","t":"F","q":"Which is Canada's **highest** court?","zq":"加拿大「最高」的法院是？","o":["The Supreme Court of Canada","The Federal Court","The Court of Appeal","The Provincial Court"],"zo":["加拿大最高法院","聯邦法院","上訴法院","省法院"],"a":0,"f":0,"e":"加拿大最高法院是全國最高的法院，是最終上訴的地方。","k":[["highest court","最高法院"]]},{"id":"D31","set":"D","ch":"08","t":"N","q":"Which of the following is **NOT** true of the rule of law in Canada?","zq":"關於加拿大的法治，下列哪一項「不正確」？","o":["Judges are above the law while serving","Judges must follow the law like everyone else","The police must follow the law","Politicians must follow the law"],"zo":["法官在任期間凌駕於法律之上","法官和所有人一樣必須守法","警察也必須守法","政治人物也必須守法"],"a":0,"f":0,"e":"法治的核心就是「沒有人凌駕於法律之上」，法官也不例外。","k":[["above the law","凌駕於法律之上"]]},{"id":"D32","set":"D","ch":"08","t":"R","q":"Which principle means a person is considered innocent until the crown proves otherwise?","zq":"哪個原則指人在被證明有罪前都算無辜？","o":["Presumption of innocence","Due process","Rule of law","Habeas corpus"],"zo":["無罪推定","正當程序","法治","人身保護令"],"a":0,"f":0,"e":"無罪推定：在被證明有罪之前，人人都是清白的。","k":[["presumption of innocence","無罪推定"]]},{"id":"D33","set":"D","ch":"09","t":"S","q":"Before the current maple leaf flag, Canada used which flag for about 100 years?","zq":"在現在的楓葉旗之前，加拿大用了大約一百年的旗子叫什麼？","o":["The Canadian Red Ensign","The Union Jack","The Fleur-de-lys flag","The Beaver Flag"],"zo":["加拿大紅船旗","英國國旗","百合花旗","海狸旗"],"a":0,"f":0,"e":"加拿大紅船旗（Red Ensign）作為國旗大約使用了一百年，直到 1965 年被楓葉旗取代。","k":[["Red Ensign","紅船旗"]]},{"id":"D34","set":"D","ch":"09","t":"F","q":"Who was the **first** Canadian to be awarded the Victoria Cross?","zq":"誰是「第一位」獲頒維多利亞十字勳章的加拿大人？","o":["Alexander Roberts Dunn","Sir Isaac Brock","Billy Bishop","John McCrae"],"zo":["亞歷山大・羅伯茨・鄧恩","艾薩克・布洛克爵士","比利・畢曉普","約翰・麥克雷"],"a":0,"f":0,"e":"亞歷山大・羅伯茨・鄧恩，生於今天的多倫多，因 1854 年巴拉克拉瓦的輕騎兵衝鋒獲頒。","k":[["first","第一位"]]},{"id":"D35","set":"D","ch":"09","t":"R","q":"In 1948, which province adopted its own flag based on the cross and the fleur-de-lys?","zq":"1948 年，哪一省採用了以十字和百合花為基礎的省旗？","o":["Quebec","Ontario","Nova Scotia","Manitoba"],"zo":["魁北克","安大略","新斯科細亞","曼尼托巴"],"a":0,"f":0,"e":"1948 年魁北克採用自己的省旗。","k":[["adopted","採用"]]},{"id":"D36","set":"D","ch":"09","t":"S","q":"The Victoria Cross is awarded for:","zq":"維多利亞十字勳章頒給什麼樣的人？","o":["The most conspicuous bravery or self-sacrifice","The longest military service","Winning a hockey championship","Founding a new political party"],"zo":["最卓越的英勇或自我犧牲","服役時間最長的人","贏得冰球冠軍","創立新政黨"],"a":0,"f":0,"e":"維多利亞十字勳章是加拿大人能獲得的最高榮譽，頒給最卓越的勇敢或自我犧牲行為。","k":[["bravery","英勇"]]},{"id":"D37","set":"D","ch":"10","t":"R","q":"In 1988, Canada enacted free trade with which country?","zq":"1988 年，加拿大與哪個國家簽訂自由貿易協定？","o":["The United States","Mexico","The United Kingdom","Japan"],"zo":["美國","墨西哥","英國","日本"],"a":0,"f":0,"e":"1988 年加美自由貿易；1994 年墨西哥加入成為 NAFTA（北美自由貿易協定）。","k":[["free trade","自由貿易"]]},{"id":"D38","set":"D","ch":"10","t":"F","q":"What share of working Canadians have jobs in service industries?","zq":"加拿大就業人口中，多少比例從事服務業？","o":["More than 75%","About 25%","About 50%","Less than 10%"],"zo":["超過 75%","大約 25%","大約 50%","不到 10%"],"a":0,"f":0,"e":"超過 75% 的就業加拿大人在服務業工作，是三大產業裡最大的一塊。","k":[["service industries","服務業"]]},{"id":"D39","set":"D","ch":"10","t":"S","q":"The border between Canada and the United States is often called:","zq":"加拿大與美國之間的邊界常被稱為什麼？","o":["The world's longest undefended border","The world's most fortified border","The Arctic frontier","The Great Divide"],"zo":["世界最長的不設防邊界","世界最堅固的邊界","北極邊疆","大分界"],"a":0,"f":0,"e":"加美邊界是世界上最長的不設防邊界，每年有數百萬人安全往來。","k":[["undefended border","不設防邊界"]]},{"id":"D40","set":"D","ch":"11","t":"R","q":"Which province is the **most easterly** point in North America and has its own time zone?","zq":"哪一省是北美洲「最東端」，並且有自己的時區？","o":["Newfoundland and Labrador","Nova Scotia","Prince Edward Island","New Brunswick"],"zo":["紐芬蘭與拉布拉多","新斯科細亞","愛德華王子島","新布藍瑞克"],"a":0,"f":0,"e":"紐芬蘭與拉布拉多是北美洲最東端，時區比大西洋時間再快半小時。","k":[["most easterly","最東端"]]},{"id":"D41","set":"D","ch":"11","t":"R","q":"New Brunswick has the second largest river system on North America's Atlantic coastline, called the:","zq":"新布藍瑞克擁有北美大西洋沿岸第二大的河流系統，叫做什麼？","o":["St. John River system","Mackenzie River system","St. Lawrence River system","Fraser River system"],"zo":["聖約翰河系統","馬更些河系統","聖羅倫斯河系統","菲沙河系統"],"a":0,"f":0,"e":"聖約翰河系統是北美大西洋沿岸第二大的河流系統。","k":[["river system","河流系統"]]},{"id":"D42","set":"D","ch":"11","t":"R","q":"At 4,200 kilometres, the Mackenzie River is the second-longest river system in North America after:","zq":"長 4,200 公里的馬更些河，是北美僅次於哪一條河的第二長河流系統？","o":["The Mississippi River","The St. Lawrence River","The Fraser River","The Colorado River"],"zo":["密西西比河","聖羅倫斯河","菲沙河","科羅拉多河"],"a":0,"f":0,"e":"馬更些河長 4,200 公里，流域面積 180 萬平方公里，僅次於密西西比河。","k":[["second-longest","第二長"]]},{"id":"D43","set":"D","ch":"11","t":"S","q":"New Brunswick was founded largely by which group of settlers?","zq":"新布藍瑞克主要是由哪一群移民建立的？","o":["United Empire Loyalists","Acadian farmers only","Klondike gold miners","French fur traders only"],"zo":["聯合帝國效忠派","僅阿卡迪亞農民","克朗代克淘金礦工","僅法國毛皮商人"],"a":0,"f":0,"e":"新布藍瑞克由聯合帝國效忠派建立，位於阿帕拉契山脈。","k":[["founded","建立"]]},{"id":"D44","set":"D","ch":"11","t":"F","q":"Which region includes Manitoba, Saskatchewan and Alberta?","zq":"哪個區域包含曼尼托巴、薩克其萬、亞伯達三省？","o":["The Prairie Provinces","The Atlantic Provinces","Central Canada","The North"],"zo":["草原省份","大西洋省份","中部加拿大","北部"],"a":0,"f":0,"e":"草原三省：曼尼托巴、薩克其萬、亞伯達。","k":[["Prairie Provinces","草原省份"]]},{"id":"D45","set":"D","ch":"00","t":"W","q":"Which statement about Canadian loyalty, according to the guide's introduction, is **TRUE**?","zq":"根據教材前言，關於加拿大人效忠的對象，哪一句「正確」？","o":["Canadians profess loyalty to a person who represents all Canadians, not to a document or a flag","Canadians swear loyalty only to the Constitution","Canadians swear loyalty to the flag as their central symbol","Canadian loyalty is defined only by the national anthem"],"zo":["加拿大人效忠的是代表全體加拿大人的一個人，而不是一份文件或一面旗子","加拿大人只效忠於憲法","加拿大人效忠的核心象徵是國旗","加拿大人的效忠只由國歌來定義"],"a":0,"f":0,"e":"教材前言原句：we profess our loyalty to **a person** who represents all Canadians, not to a document, a banner or an abstract symbol——這個人就是君主。","k":[["profess loyalty","效忠"]]},{"id":"D46","set":"D","ch":"00","t":"S","q":"The Oath of Citizenship states you will observe the laws of Canada, \"including the Constitution, which recognizes and affirms\" whose rights?","zq":"誓詞裡說要遵守加拿大法律，「包括憲法，憲法承認並確認」了誰的權利？","o":["The Aboriginal and treaty rights of First Nations, Inuit and Métis peoples","The property rights of all landowners","The voting rights of permanent residents","The trade rights of provincial governments"],"zo":["第一民族、因紐特人、梅蒂斯人的原住民與條約權利","所有地主的財產權","永久居民的投票權","各省政府的貿易權"],"a":0,"f":0,"e":"誓詞原文：...including the Constitution, which recognizes and affirms the Aboriginal and treaty rights of First Nations, Inuit and Métis peoples...","k":[["recognizes and affirms","承認並確認"]]},{"id":"D47","set":"D","ch":"00","t":"T","q":"True or False: According to the guide, Canadians pledge loyalty mainly to the Constitution as a document.","zq":"是非題：根據教材，加拿大人效忠的主要對象是憲法這份文件。","o":["True","False"],"zo":["對","錯"],"a":1,"f":1,"e":"錯。教材明確說效忠的是「代表全體加拿大人的一個人」（君主），不是文件、旗子或象徵。","k":[["Constitution","憲法"]]},{"id":"D48","set":"D","ch":"01","t":"N","q":"Which of the following is **NOT** one of the two basic requirements tested for citizenship?","zq":"下列哪一項「不是」入籍考試測驗的兩大基本要求之一？","o":["Proof of steady employment","Knowledge of Canada and the rights and responsibilities of citizenship","Adequate knowledge of English or French","Meeting the age and language requirements set out in the regulations"],"zo":["穩定工作的證明","對加拿大及公民權利責任的知識","足夠的英語或法語能力","符合規定的年齡與語言要求"],"a":0,"f":0,"e":"兩大基本要求是：加拿大知識與公民權責的知識、足夠的英法語能力。工作證明不是考試項目。","k":[["requirement","要求"]]},{"id":"D49","set":"D","ch":"01","t":"W","q":"Which statement about the citizenship ceremony is **TRUE**?","zq":"關於入籍典禮，哪一句「正確」？","o":["You take the Oath, sign the oath form, and receive your Citizenship Certificate","You must pay a fee at the ceremony to receive your certificate","Family and friends are not allowed to attend","The ceremony replaces the written test"],"zo":["你會宣誓、簽署誓詞表格，並領取公民證","你必須在典禮上付費才能領證","家人朋友不能出席","典禮取代筆試"],"a":0,"f":0,"e":"典禮上會宣誓、簽署誓詞表格、領取公民證；官方鼓勵你帶家人朋友一起慶祝。","k":[["Citizenship Certificate","公民證"]]},{"id":"D50","set":"D","ch":"01","t":"C","q":"You take the citizenship test but do not pass. What happens next?","zq":"你參加了入籍考試但沒通過，接下來會怎樣？","o":["You receive a notification about the next steps, such as an interview or another attempt","Your application is permanently cancelled with no recourse","You are automatically deported","You lose your permanent resident status immediately"],"zo":["你會收到通知，說明後續步驟，例如面談或再次應試","你的申請會被永久取消、無法補救","你會被自動遣返","你會立刻失去永久居民身分"],"a":0,"f":0,"e":"沒通過考試會收到通知說明下一步，通常是安排面談或再試一次，不是直接被拒絕或遣返。","k":[["next steps","後續步驟"]]},{"id":"D51","set":"D","ch":"12","t":"S","q":"The capital of Ontario is:","zq":"安大略省的首府是：","o":["Toronto","Ottawa","Hamilton","Kingston"],"zo":["多倫多","渥太華","漢彌爾頓","京士頓"],"a":0,"f":0,"e":"安大略的省會是多倫多；渥太華雖然在安大略境內，卻是「加拿大」的首都，不是安大略的省會。","k":[["capital","首府"]]},{"id":"D52","set":"D","ch":"12","t":"C","q":"Before your citizenship interview, you are told to look up your own information online at elections.ca. What should you find and memorize?","zq":"典禮或面談前，教材要你上 elections.ca 查詢並背熟什麼？","o":["Your federal riding and the name of your MP","The Prime Minister's home address","Your own SIN number","The Governor General's travel schedule"],"zo":["你的聯邦選區與你的國會議員姓名","總理的住家地址","你自己的社會保險號碼","總督的出訪行程"],"a":0,"f":0,"e":"到 elections.ca 輸入郵遞區號，可以查出自己的聯邦選區和國會議員，這是安大略／本地考題常問的內容。","k":[["riding","選區"]]},{"id":"D53","set":"D","ch":"12","t":"W","q":"Which statement about the founding of Confederation is **TRUE**?","zq":"關於聯邦成立，哪一句「正確」？","o":["Nova Scotia, New Brunswick and the Province of Canada (which became Ontario and Quebec) joined to form the Dominion of Canada on July 1, 1867","Only Ontario and Quebec existed before Confederation","Confederation happened in 1867 with ten provinces joining at once","The Province of Canada remained one province after 1867"],"zo":["新斯科細亞、新布藍瑞克，以及後來拆成安大略與魁北克的加拿大省，於 1867 年 7 月 1 日聯合組成加拿大自治領","聯邦成立前只有安大略和魁北克存在","聯邦是 1867 年十個省一起加入","加拿大省在 1867 年後仍然維持一個省"],"a":0,"f":0,"e":"加拿大省（Province of Canada）在聯邦成立時被拆成安大略與魁北克兩省，和新斯科細亞、新布藍瑞克一起組成 1867 年的自治領。","k":[["Dominion of Canada","加拿大自治領"]]},{"id":"E01","set":"E","ch":"02","t":"F","q":"What is the **minimum** age to vote in a federal election?","zq":"聯邦選舉投票的「最低」年齡是？","o":["18","16","19","21"],"zo":["18 歲","16 歲","19 歲","21 歲"],"a":0,"f":0,"e":"選舉日當天滿 18 歲、是公民、在選民名冊上，三個條件缺一不可。","k":[["minimum","最低"]]},{"id":"E02","set":"E","ch":"02","t":"C","q":"A friend tells you citizenship only comes with rights, no obligations. Is this correct?","zq":"朋友說公民身分只有權利、沒有義務，這樣對嗎？","o":["No — citizens also have responsibilities such as obeying the law and voting","Yes, Canada has no responsibilities for citizens","Only new citizens have responsibilities","Responsibilities only apply during an election year"],"zo":["不對——公民也有守法、投票等責任","對，加拿大對公民沒有任何要求","只有新公民才有責任","責任只在選舉年才適用"],"a":0,"f":0,"e":"公民身分是權利與責任並存：守法、照顧家人、陪審、投票、助人、保護環境，六大責任缺一不可。","k":[["obligation","義務"]]},{"id":"E03","set":"E","ch":"02","t":"S","q":"Which right lets a Canadian citizen move to another province to take a job?","zq":"哪一項權利讓加拿大公民可以搬到別省工作？","o":["Mobility rights","Legal rights","Equality rights","Language rights"],"zo":["遷徙權","法律權利","平等權","語言權"],"a":0,"f":0,"e":"遷徙權：可以在加拿大任何地方居住與工作。","k":[["mobility rights","遷徙權"]]},{"id":"E04","set":"E","ch":"02","t":"W","q":"Which statement about Canadian law is **TRUE**?","zq":"關於加拿大法律，哪一句「正確」？","o":["The law applies to everyone, including judges, politicians and the police","Politicians are exempt from the law while in office","Only citizens must obey the law","Judges can overrule any law they personally dislike"],"zo":["法律適用於每一個人，包括法官、政治人物與警察","政治人物在任期間不受法律約束","只有公民必須守法","法官可以推翻自己不喜歡的法律"],"a":0,"f":0,"e":"官方原文：The law in Canada applies to everyone, including judges, politicians and the police。","k":[["applies to everyone","適用於每一個人"]]},{"id":"E05","set":"E","ch":"03","t":"F","q":"Among the three groups of Aboriginal peoples, which is the **smallest** in population?","zq":"原住民三大群體中，人口「最少」的是哪一群？","o":["Inuit","First Nations","Métis","They are equal in size"],"zo":["因紐特人","第一民族","梅蒂斯人","三者人數相同"],"a":0,"f":0,"e":"約 65% 第一民族、30% 梅蒂斯人、4% 因紐特人——因紐特人人數最少。","k":[["smallest","最少"]]},{"id":"E06","set":"E","ch":"03","t":"R","q":"The government apologized to **Japanese Canadians** in which year?","zq":"加拿大政府向「日裔加拿大人」道歉是在哪一年？","o":["1988","2006","2008","1971"],"zo":["1988 年","2006 年","2008 年","1971 年"],"a":0,"f":0,"e":"1988 年為二戰期間日裔加拿大人的遷移與拘留道歉；2006 年是人頭稅、2008 年是寄宿學校。","k":[["apologized","道歉"]]},{"id":"E07","set":"E","ch":"03","t":"W","q":"Which statement about multiculturalism in the guide is **TRUE**?","zq":"關於「多元文化」，官方教材裡哪一句「正確」？","o":["Canadians celebrate the gift of one another's presence and work hard to respect diversity","Only new immigrants are expected to adopt Canadian traditions","Multiculturalism means everyone must give up their own traditions","Multiculturalism applies only to official-language communities"],"zo":["加拿大人珍惜彼此存在的這份禮物，並努力尊重多元","只有新移民需要接受加拿大傳統","多元文化代表每個人都必須放棄自己的傳統","多元文化只適用於官方語言社群"],"a":0,"f":0,"e":"教材原句就是「Canadians celebrate the gift of one another's presence and work hard to respect diversity」，強調彼此尊重而非放棄自己的文化。","k":[["diversity","多元"]]},{"id":"E08","set":"E","ch":"03","t":"S","q":"The word \"**Aboriginal**\" in the Canadian context refers to which three peoples?","zq":"在加拿大脈絡下，「Aboriginal（原住民）」一詞指哪三個民族？","o":["First Nations, Inuit and Métis","English, French and Aboriginal","Acadians, Québécois and Loyalists","Anglophones and Francophones"],"zo":["第一民族、因紐特人、梅蒂斯人","英裔、法裔、原住民","阿卡迪亞人、魁北克人、效忠派","英語族群與法語族群"],"a":0,"f":0,"e":"加拿大憲法所稱的原住民族包含第一民族、因紐特人、梅蒂斯人三者。","k":[["Aboriginal","原住民"]]},{"id":"E09","set":"E","ch":"04","t":"F","q":"What is the capital of Alberta?","zq":"亞伯達省的首府是哪裡？","o":["Edmonton","Calgary","Regina","Winnipeg"],"zo":["艾德蒙頓","卡加利","里賈納","溫尼伯"],"a":0,"f":0,"e":"卡加利是最大城，但艾德蒙頓才是首府。","k":[["capital","首府"]]},{"id":"E10","set":"E","ch":"04","t":"S","q":"In Inuktitut, \"Nunavut\" means:","zq":"努納福特（Nunavut）在因紐特語裡的意思是：","o":["Our land","Village","The people","Northern home"],"zo":["我們的土地","村莊","人民","北方家園"],"a":0,"f":0,"e":"Nunavut = our land；kanata = village；Inuit = the people。三個容易搞混。","k":[["means","意思是"]]},{"id":"E11","set":"E","ch":"04","t":"W","q":"Which statement about the Canadian Pacific Railway is **TRUE**?","zq":"關於加拿大太平洋鐵路，哪一句「正確」？","o":["It was built by both European and Chinese labour, financed by British and American investors","It was built entirely by government soldiers","It was funded entirely by the Hudson's Bay Company","No Chinese workers were involved in its construction"],"zo":["由歐洲與華人勞工共同興建，英美投資者出資","完全由政府軍人興建","完全由哈德遜灣公司出資","完全沒有華工參與"],"a":0,"f":0,"e":"官方原文：built by both European and Chinese labour；financed by British and American investors。","k":[["financed","出資"]]},{"id":"E12","set":"E","ch":"04","t":"S","q":"Quebec's movement for sovereignty was defeated in referendums held in:","zq":"魁北克主權運動在哪兩次公投中失敗？","o":["1980 and 1995","1970 and 1985","1982 and 1999","1975 and 1990"],"zo":["1980 年和 1995 年","1970 年和 1985 年","1982 年和 1999 年","1975 年和 1990 年"],"a":0,"f":0,"e":"第一次公投 1980 年、第二次 1995 年，主權運動都以些微差距失敗。","k":[["referendum","公投"]]},{"id":"E13","set":"E","ch":"04","t":"C","q":"A student says British Columbia joined Confederation for free, with no conditions. Is that accurate?","zq":"有學生說卑詩省是無條件加入聯邦的，這樣對嗎？","o":["No — Ottawa had to promise a railway to the West Coast","Yes, no conditions were attached","No — B.C. had to pay Ottawa a large sum","No — B.C. had to give up its coastline"],"zo":["不對——渥太華必須承諾建一條通往西岸的鐵路","對，沒有附帶任何條件","不對——卑詩省必須付渥太華一大筆錢","不對——卑詩省必須放棄海岸線"],"a":0,"f":0,"e":"1871 年卑詩省加入的條件是渥太華承諾興建通往西岸的鐵路，也就是後來的 CPR。","k":[["condition","條件"]]},{"id":"E14","set":"E","ch":"04","t":"S","q":"Until 1982, July 1 was celebrated under what name?","zq":"1982 年以前，7 月 1 日這一天叫做什麼名字？","o":["Dominion Day","Confederation Day","Empire Day","Founders' Day"],"zo":["自治領日","聯邦日","帝國日","建國者日"],"a":0,"f":0,"e":"1982 年以前叫 Dominion Day，之後改名 Canada Day。","k":[["Dominion Day","自治領日"]]},{"id":"E15","set":"E","ch":"05","t":"S","q":"The North Atlantic Treaty Organization (NATO) is best described as:","zq":"北大西洋公約組織（NATO）最好的描述是：","o":["A military alliance of Western democratic countries","A trade agreement between Canada and the U.S.","An international sports federation","A United Nations peacekeeping unit"],"zo":["西方民主國家組成的軍事同盟","加美之間的貿易協定","國際體育組織","聯合國維和單位"],"a":0,"f":0,"e":"加拿大與其他西方民主國家共同組成軍事同盟 NATO，另外也和美國組成 NORAD（北美航太防禦司令部）。","k":[["military alliance","軍事同盟"]]},{"id":"E16","set":"E","ch":"05","t":"R","q":"The Official Languages Act, which guarantees French and English services across the federal government, was passed in:","zq":"保障聯邦政府全國提供法語與英語服務的《官方語言法》通過於哪一年？","o":["1969","1982","1867","1971"],"zo":["1969 年","1982 年","1867 年","1971 年"],"a":0,"f":0,"e":"1969 年《官方語言法》(Official Languages Act)。","k":[["guarantees","保障"]]},{"id":"E17","set":"E","ch":"05","t":"S","q":"Sir Frederick Banting and Charles Best made history in 1922 by discovering:","zq":"班廷爵士與貝斯特在 1922 年因發現什麼而留名青史？","o":["Insulin","Penicillin","The telephone","Radar"],"zo":["胰島素","盤尼西林","電話","雷達"],"a":0,"f":0,"e":"1922 年發現胰島素，用於治療糖尿病，救了全球數百萬人的性命。","k":[["insulin","胰島素"]]},{"id":"E18","set":"E","ch":"05","t":"C","q":"Someone claims Canada has never joined any international military alliance. Is this correct?","zq":"有人說加拿大從未加入任何國際軍事同盟，這樣對嗎？","o":["No — Canada is a member of NATO and, with the U.S., of NORAD","Yes, Canada avoids all alliances","No — Canada only joined the United Nations","Only during wartime does Canada join alliances"],"zo":["不對——加拿大是 NATO 成員，並與美國共組 NORAD","對，加拿大避開所有同盟","不對——加拿大只加入了聯合國","只有戰時加拿大才會加入同盟"],"a":0,"f":0,"e":"加拿大是 NATO 成員國，也與美國共組北美航太防禦司令部 NORAD。","k":[["alliance","同盟"]]},{"id":"E19","set":"E","ch":"06","t":"F","q":"Which is the **FIRST** step a bill goes through in Parliament?","zq":"法案在國會經過的「第一」個步驟是？","o":["First Reading","Royal Assent","Committee Stage","Third Reading"],"zo":["一讀","御准","委員會階段","三讀"],"a":0,"f":0,"e":"一讀：法案被視為第一次宣讀並印製，是流程的起點。","k":[["first step","第一步"]]},{"id":"E20","set":"E","ch":"06","t":"S","q":"At the municipal level, government is mainly responsible for things like:","zq":"市政府層級主要負責哪些事？","o":["Snow removal, firefighting and public transit","National defence and foreign policy","Currency and criminal law","Citizenship and immigration"],"zo":["除雪、消防、大眾運輸","國防和外交政策","貨幣與刑法","公民身分與移民"],"a":0,"f":0,"e":"市政府管的是除雪、消防、大眾運輸、地方法規這類在地事務；國防外交貨幣刑法是聯邦的。","k":[["municipal","市政的"]]},{"id":"E21","set":"E","ch":"06","t":"S","q":"Each electoral riding elects how many Members of Parliament?","zq":"每個選區選出幾位國會議員？","o":["One","Two","Three","It varies by population"],"zo":["一位","兩位","三位","依人口而定"],"a":0,"f":0,"e":"每個選區選出一位 MP，得票最多者當選。","k":[["riding","選區"]]},{"id":"E22","set":"E","ch":"06","t":"C","q":"Your city wants to change garbage collection days. Which level of government makes that decision?","zq":"你的城市想更改垃圾收集日，是哪一級政府的決定？","o":["Municipal government","Federal government","Provincial government","The Senate"],"zo":["市政府","聯邦政府","省政府","參議院"],"a":0,"f":0,"e":"垃圾收集、除雪這類地方事務由市政府負責。","k":[["municipal","市政的"]]},{"id":"E23","set":"E","ch":"06","t":"F","q":"What is the **LAST** stage a bill goes through before it becomes law?","zq":"法案成為法律前的「最後」一個階段是？","o":["Royal Assent","First Reading","Second Reading","Committee Stage"],"zo":["御准","一讀","二讀","委員會階段"],"a":0,"f":0,"e":"兩院都通過後，由總督代表君主給予御准（Royal Assent），法案才正式成為法律。","k":[["last stage","最後階段"]]},{"id":"E24","set":"E","ch":"07","t":"S","q":"Before voting, Elections Canada mails every registered voter a:","zq":"投票前，選舉局會寄給每位登記選民什麼？","o":["Voter information card","A sample ballot to keep","A list of all candidates in the country","A tax refund form"],"zo":["選民資訊卡","一張留存用的樣本選票","全國所有候選人名單","退稅表格"],"a":0,"f":0,"e":"選民資訊卡列出投票的時間與地點。","k":[["voter information card","選民資訊卡"]]},{"id":"E25","set":"E","ch":"07","t":"C","q":"You go to your polling station but forgot your voter information card. What should you do?","zq":"你到了投票站卻忘記帶選民資訊卡，該怎麼辦？","o":["Bring proof of identity and address instead","You cannot vote without the card","Ask a stranger to vote using your name","Wait for the next election"],"zo":["改帶身分與地址證明就可以","沒有卡就不能投票","請陌生人代替你用你的名字投票","等下次選舉"],"a":0,"f":0,"e":"卡片是提醒用的，只要能證明身分和地址，一樣可以投票。","k":[["proof of identity","身分證明"]]},{"id":"E26","set":"E","ch":"07","t":"F","q":"What is the **minimum age** requirement, combined with citizenship, to vote federally?","zq":"除了公民身分，聯邦投票另一個「最低」門檻是？","o":["18 years old on election day","16 years old on election day","21 years old on election day","No age requirement"],"zo":["選舉日當天滿 18 歲","選舉日當天滿 16 歲","選舉日當天滿 21 歲","沒有年齡限制"],"a":0,"f":0,"e":"公民身分＋選舉日滿 18 歲＋在選民名冊上，三者缺一不可。","k":[["age requirement","年齡門檻"]]},{"id":"E27","set":"E","ch":"08","t":"S","q":"In most provinces, the trial-level court is sometimes called the:","zq":"在大多數省份，審判層級的法院有時被稱為什麼？","o":["Court of Queen's Bench (or King's Bench)","The Supreme Court of Canada","The House of Commons","The Senate"],"zo":["女王座法院（或國王座法院）","加拿大最高法院","下議院","參議院"],"a":0,"f":0,"e":"教材原文寫 Court of Queen's Bench；伊莉莎白二世過世、查理三世即位後，多數省份已改名 King's Bench，但 2021 版教材用的還是舊名。","k":[["Queen's Bench","女王座法院"]]},{"id":"E28","set":"E","ch":"08","t":"S","q":"\"Due process\" means the government must:","zq":"「正當程序」的意思是政府必須：","o":["Respect every legal right a person is entitled to under the law","Finish every court case within one week","Let police skip the courts in urgent cases","Only apply to criminal cases"],"zo":["尊重每個人依法享有的所有法律權利","一週內結束每一件案子","緊急案件可讓警察跳過法院","只適用於刑事案件"],"a":0,"f":0,"e":"正當程序：政府必須尊重每個人依法享有的所有法律權利。","k":[["due process","正當程序"]]},{"id":"E29","set":"E","ch":"08","t":"C","q":"You cannot afford a lawyer for a legal problem. What is available to help?","zq":"你請不起律師處理法律問題，有什麼資源可以幫忙？","o":["Legal aid services","Nothing — only people with money can go to court","You must represent the government instead","Only the police can help"],"zo":["法律援助服務","沒有——只有有錢人能上法院","你必須代表政府出庭","只有警察能幫忙"],"a":0,"f":0,"e":"法律援助（legal aid）提供免費或低收費的協助。","k":[["legal aid","法律援助"]]},{"id":"E30","set":"E","ch":"09","t":"R","q":"The colours of the Canadian flag, red and white, come from the flag of which institution, founded in 1876?","zq":"加拿大國旗的紅白配色，來自 1876 年創立的哪個機構的旗幟？","o":["The Royal Military College, Kingston","The Hudson's Bay Company","The Supreme Court of Canada","The University of Toronto"],"zo":["京士頓皇家軍事學院","哈德遜灣公司","加拿大最高法院","多倫多大學"],"a":0,"f":0,"e":"紅白圖案來自 1876 年創立的京士頓皇家軍事學院旗幟。","k":[["founded","創立"]]},{"id":"E31","set":"E","ch":"09","t":"R","q":"Canada started its own honours system, the Order of Canada, in which year?","zq":"加拿大自己的榮譽制度「加拿大勳章」創立於哪一年？","o":["1967","1965","1982","1957"],"zo":["1967 年","1965 年","1982 年","1957 年"],"a":0,"f":0,"e":"1967 年，也就是聯邦成立一百週年，加拿大開始自己的榮譽制度。","k":[["Order of Canada","加拿大勳章"]]},{"id":"E32","set":"E","ch":"09","t":"S","q":"Canada's national motto, \"A mari usque ad mare,\" means:","zq":"加拿大的國家格言「A mari usque ad mare」意思是：","o":["From sea to sea","Strong and free","One nation, many peoples","Peace, order and good government"],"zo":["從海到海","強大而自由","一個國家，多元民族","和平、秩序與良好政府"],"a":0,"f":0,"e":"拉丁文，字面意思是「從海到海」，一戰後與國徽一起採用。","k":[["motto","格言"]]},{"id":"E33","set":"E","ch":"09","t":"T","q":"True or False: The Canadian flag was first raised in 1965.","zq":"是非題：加拿大國旗在 1965 年第一次升起。","o":["True","False"],"zo":["對","錯"],"a":0,"f":1,"e":"對。新的楓葉旗在 1965 年首次升起，取代用了約 100 年的紅船旗。","k":[["first raised","第一次升起"]]},{"id":"E34","set":"E","ch":"09","t":"C","q":"A ceremony celebrates the \"gift\" of over one million immigrants passing through a Halifax pier between 1928 and 1971. Which symbol/site is this?","zq":"一場典禮紀念 1928 到 1971 年間超過一百萬移民經過哈利法克斯的一座碼頭，指的是哪個地標？","o":["Pier 21","The Peace Tower","Confederation Bridge","The Parliament Buildings"],"zo":["21 號碼頭","和平塔","聯邦大橋","國會大廈"],"a":0,"f":0,"e":"21 號碼頭是 1928–1971 年超過百萬移民進入加拿大的門戶，現在是國家博物館。","k":[["gateway","門戶"]]},{"id":"E35","set":"E","ch":"10","t":"S","q":"NAFTA was replaced in 2020 by which agreement?","zq":"北美自由貿易協定（NAFTA）在 2020 年被哪個協定取代？","o":["CUSMA (Canada-United States-Mexico Agreement)","The G7 Accord","The Commonwealth Trade Pact","The Pacific Alliance"],"zo":["加美墨協定 CUSMA","G7 協定","大英國協貿易協定","太平洋聯盟"],"a":0,"f":0,"e":"CUSMA 在 2020 年取代 NAFTA；2021 版教材裡寫的還是 NAFTA。","k":[["replaced","取代"]]},{"id":"E36","set":"E","ch":"10","t":"N","q":"Which of the following is **NOT** one of Canada's three main types of industries?","zq":"下列哪一項「不是」加拿大三大類產業之一？","o":["Agriculture-only economy","Service industries","Manufacturing industries","Natural resources industries"],"zo":["純農業經濟","服務業","製造業","天然資源業"],"a":0,"f":0,"e":"三大類是服務業、製造業、天然資源業，沒有「純農業經濟」這個分類。","k":[["main types","主要類型"]]},{"id":"E37","set":"E","ch":"10","t":"R","q":"The Peace Arch at Blaine, Washington is inscribed with words meaning:","zq":"位於華盛頓州 Blaine 的和平拱門上刻著的話，意思是？","o":["Children of a common mother, living together in unity","Two nations, one border","From sea to sea","Peace, order and good government"],"zo":["同一位母親的孩子，和睦同住","兩個國家，一條邊界","從海到海","和平、秩序與良好政府"],"a":0,"f":0,"e":"和平拱門刻著「children of a common mother」與「brethren dwelling together in unity」，象徵加美友好。","k":[["inscribed","刻著"]]},{"id":"E38","set":"E","ch":"11","t":"F","q":"Canada is the **second largest** country on Earth. What is its approximate area?","zq":"加拿大是地球上「第二大」國家，面積大約是多少？","o":["10 million square kilometres","5 million square kilometres","20 million square kilometres","1 million square kilometres"],"zo":["一千萬平方公里","五百萬平方公里","兩千萬平方公里","一百萬平方公里"],"a":0,"f":0,"e":"加拿大約一千萬平方公里，是地球上第二大的國家。","k":[["second largest","第二大"]]},{"id":"E39","set":"E","ch":"11","t":"S","q":"Prince Edward Island is connected to mainland Canada by:","zq":"愛德華王子島與加拿大本土之間，是靠什麼相連的？","o":["The Confederation Bridge","A tunnel","The Last Spike railway line","It is not connected; ferry only"],"zo":["聯邦大橋","一條隧道","最後道釘鐵路線","沒有相連，只能搭渡輪"],"a":0,"f":0,"e":"聯邦大橋是世界上最長的連續多跨橋之一，連接愛德華王子島與本土。","k":[["Confederation Bridge","聯邦大橋"]]},{"id":"E40","set":"E","ch":"11","t":"F","q":"Montreal is Canada's second largest city and the second largest mainly French-speaking city in the world after:","zq":"蒙特婁是加拿大第二大城，也是世界第二大主要說法語的城市，僅次於哪一個城市？","o":["Paris","Brussels","Geneva","Marseille"],"zo":["巴黎","布魯塞爾","日內瓦","馬賽"],"a":0,"f":0,"e":"蒙特婁是僅次於巴黎的世界第二大法語城市，以文化多元聞名。","k":[["French-speaking","說法語的"]]},{"id":"E41","set":"E","ch":"11","t":"N","q":"Which of the following oceans does **NOT** border Canada?","zq":"下列哪個海洋「不」與加拿大相鄰？","o":["The Indian Ocean","The Pacific Ocean","The Atlantic Ocean","The Arctic Ocean"],"zo":["印度洋","太平洋","大西洋","北冰洋"],"a":0,"f":0,"e":"加拿大三面環海：太平洋、大西洋、北冰洋，印度洋不相鄰。","k":[["border","相鄰"]]},{"id":"E42","set":"E","ch":"11","t":"C","q":"A traveller wants to see the world's highest tides in Canada. Which body of water should they visit?","zq":"旅客想看世界最高的潮汐，該去加拿大的哪個海灣？","o":["The Bay of Fundy","Hudson Bay","Georgian Bay","James Bay"],"zo":["芬地灣","哈德遜灣","喬治亞灣","詹姆斯灣"],"a":0,"f":0,"e":"芬地灣（在新斯科細亞與新布藍瑞克之間）擁有全球最高的潮汐紀錄。","k":[["highest tides","最高潮汐"]]},{"id":"E43","set":"E","ch":"00","t":"R","q":"Since September 2022, the Oath of Citizenship names which Sovereign, even though this guide was printed in 2021 and still says Queen Elizabeth II?","zq":"雖然這本教材印於 2021 年、寫的還是伊莉莎白二世，但 2022 年 9 月起誓詞裡實際要唸的君主名字是誰？","o":["King Charles the Third","Queen Elizabeth the Second","Prince William","Queen Camilla"],"zo":["查理三世國王","伊莉莎白二世女王","威廉王子","卡蜜拉王后"],"a":0,"f":0,"e":"2022 年 9 月伊莉莎白二世過世，查理三世即位；宣誓時要唸的是 King Charles the Third，不是教材印的舊名字。","k":[["Sovereign","君主"]]},{"id":"E44","set":"E","ch":"00","t":"C","q":"At your citizenship ceremony, the officiant asks you to repeat the Oath. Whose name should you say for the Sovereign, today?","zq":"在你的入籍典禮上，主持人請你複誦誓詞，今天你應該唸出誰的名字作為君主？","o":["King Charles the Third","Queen Elizabeth the Second","Governor General Louise Arbour","Prime Minister Mark Carney"],"zo":["查理三世國王","伊莉莎白二世女王","總督露易絲・阿爾布爾","總理馬克・卡尼"],"a":0,"f":0,"e":"誓詞裡效忠的對象是君主本人，現在是查理三世，不是總督也不是總理——總督只是代表君主。","k":[["Oath","誓詞"]]},{"id":"E45","set":"E","ch":"00","t":"N","q":"Which of the following is **NOT** something Canada is described as, according to the guide's introduction?","zq":"根據教材前言，下列哪一項「不是」加拿大被描述的樣子？","o":["A republic led by an elected president","A constitutional monarchy","A parliamentary democracy","A federal state"],"zo":["由民選總統領導的共和國","君主立憲國家","議會民主國家","聯邦制國家"],"a":0,"f":0,"e":"教材原句：Canada is a constitutional monarchy, a parliamentary democracy and a federal state——沒有「共和國」這回事。","k":[["federal state","聯邦制國家"]]},{"id":"E46","set":"E","ch":"01","t":"F","q":"Adult applicants of what age and older do **NOT** need to write the citizenship test?","zq":"幾歲以上的成年申請人「不需要」寫入籍考試？","o":["55","65","50","60"],"zo":["55 歲","65 歲","50 歲","60 歲"],"a":0,"f":0,"e":"55 歲以上的成年申請人不需要參加筆試，但仍需符合其他條件。","k":[["do not need to write","不需要考試"]]},{"id":"E47","set":"E","ch":"01","t":"S","q":"If you pass the citizenship test, what document will you receive next?","zq":"通過入籍考試後，你接下來會收到什麼文件？","o":["A Notice to Appear to Take the Oath of Citizenship","A permanent resident card renewal","A new passport automatically","A tax refund form"],"zo":["出席宣誓典禮的通知","永久居民卡更新通知","自動核發的新護照","退稅表格"],"a":0,"f":0,"e":"通過考試並符合其他條件後，會收到出席宣誓典禮的通知，上面寫著日期、時間、地點。","k":[["Notice to Appear","出席通知"]]},{"id":"E48","set":"E","ch":"01","t":"R","q":"Immigrants between which ages must show adequate knowledge of English or French to become citizens?","zq":"哪個年齡範圍的移民必須證明有足夠的英語或法語能力才能入籍？","o":["18 to 54","16 to 65","18 to 65","21 to 60"],"zo":["18 到 54 歲","16 到 65 歲","18 到 65 歲","21 到 60 歲"],"a":0,"f":0,"e":"18 到 54 歲的申請人必須證明有足夠的英語或法語能力；55 歲以上者不需要考試，但仍要符合其他要求。","k":[["adequate knowledge","足夠的能力"]]},{"id":"E49","set":"E","ch":"12","t":"N","q":"Which of the following is **NOT true**: Ottawa is the capital of Ontario.","zq":"是非題（換句話說）：「渥太華是安大略省的首府」這句話是錯的，為什麼？","o":["Because Ottawa is the capital of Canada, while Toronto is the capital of Ontario","Because Ontario has no capital city","Because Ottawa is actually in Quebec","Because Toronto is the capital of Canada"],"zo":["因為渥太華是加拿大的首都，多倫多才是安大略的省會","因為安大略沒有省會","因為渥太華其實在魁北克","因為多倫多才是加拿大的首都"],"a":0,"f":0,"e":"渥太華＝加拿大首都；多倫多＝安大略省會。兩個常常被考生搞混。","k":[["capital of Canada","加拿大首都"]]},{"id":"E50","set":"E","ch":"12","t":"R","q":"For test-takers in Ontario, which two provincial roles are you specifically told to know the current holders of?","zq":"安大略考生特別被要求記住哪兩個省級職位的現任人選？","o":["The Premier and the Lieutenant Governor of Ontario","The Mayor of Toronto and the Chief of Police","The Speaker of the House and the Chief Justice","The Governor General and the Prime Minister"],"zo":["安大略省長與安大略省督","多倫多市長與警察局長","眾議院議長與首席大法官","總督與總理"],"a":0,"f":0,"e":"安大略考生要記住現任省長（Premier）與省督（Lieutenant Governor），這是官方教材特別提醒的地方性題目。","k":[["Premier","省長"]]}];